export const OPENAPI_JSON: string = "{\n  \"openapi\": \"3.1.0\",\n  \"info\": {\n    \"title\": \"Mythicshot API\",\n    \"version\": \"0.1.19\",\n    \"description\": \"Upload, publish and manage interactive product tours. This is the API Mythicshot itself uses.\\n\\n## Get connected\\n\\nEvery request except the health check and the two sign-in requests carries a token, as the header `Authorization: Bearer YOUR_TOKEN`, or a session cookie (see below). A token starts with \\\"dp_\\\" and is 43 characters long. It acts only inside its own workspace: another workspace's tour answers 404, the same as one that does not exist.\\n\\nThe first request to try answers with your workspace's name and the server's version:\\n\\n```\\ncurl https://YOUR-SITE/api/v1/me -H \\\"Authorization: Bearer YOUR_TOKEN\\\"\\n```\\n\\n## Signing in and sessions\\n\\nThe site's own pages sign a person in with a link sent by mail: POST /api/v1/signin/request mails the link, and POST /api/v1/signin/complete turns the code in it into a session. The link works once and for 15 minutes. The session is a cookie, __Host-dp_session, on the app address only (on a server with one address, on that address); it lasts 30 days from its last use. Every request that lists the session can be sent with it instead of a token, and acts in the account's one workspace.\\n\\nA signed-in person changes the account's email address in two steps: POST /api/v1/account/email mails a link to the new address, and POST /api/v1/account/email/confirm, sent with the code in that link from the same account's session, makes the change, once and within 15 minutes. The old address is then sent a notice. Both need the session; a token cannot change an address.\\n\\nA request with a session that changes anything (any method but GET and HEAD) must come from the site's own pages: its Origin must be the address it is sent to, and it must carry the session's anti-forgery value in the header `X-Csrf-Token`, which GET /api/v1/session gives. A token and a session cookie together are refused.\\n\\nThe documentation page never sends a cookie, so a session cannot be tried from it; with a token, try the requests that take one.\\n\\n## Errors\\n\\nEvery refusal is JSON with an error code and, mostly, a detail in plain words: `{\\\"error\\\":\\\"bad_title\\\",\\\"detail\\\":\\\"the title must not be empty\\\"}`. The codes are stable; the detail text may change.\\n\\nSome answers can come from any request and are not repeated on each one:\\n\\n- `401 {\\\"error\\\":\\\"unauthorized\\\"}`, with no detail: the token or session cookie is missing, malformed, unknown, expired or revoked, or a session cookie was sent to the tours address.\\n- `400 {\\\"error\\\":\\\"mixed_credentials\\\",\\\"detail\\\":\\\"send a token or a session cookie, not both\\\"}`: the request carries a token and a session cookie.\\n- `403 {\\\"error\\\":\\\"bad_origin\\\",\\\"detail\\\":\\\"this request must come from the site's own pages\\\"}`: a change made with a session did not come from a page of the address it was sent to.\\n- `403 {\\\"error\\\":\\\"bad_csrf\\\",\\\"detail\\\":\\\"the anti-forgery header is missing or wrong\\\"}`: a change made with a session lacks the session's X-Csrf-Token.\\n- `404 {\\\"error\\\":\\\"not_found\\\"}`, with no detail: no request has that address.\\n- `421` with nothing in it: on a server with two addresses, the request was sent to another host name.\\n- `500 {\\\"error\\\":\\\"internal\\\"}`: the server failed; nothing about the failure is given.\\n- `500 {\\\"error\\\":\\\"misconfigured\\\"}`: on Cloudflare, the two addresses in the settings cannot be used together; every request answers this until they are fixed.\\n\\nThe admin routes (under /api/v1/admin/) answer every refusal, the 400 and the two 403s above included, with the one `404 {\\\"error\\\":\\\"not_found\\\"}`.\\n\\n## Requests that work in steps\\n\\nPublish, unpublish and delete may need several requests for a large tour. Each is safe to send again: send the same request until it answers 200 or 204.\\n\\n## Limits\\n\\n- 200 steps in one upload, and 20 notes on a step.\\n- The manifest: 262,144 bytes.\\n- A step image: 2,000,000 bytes and 4,096 pixels on a side, PNG or JPEG.\\n- The logo: 200,000 bytes and 512 pixels on a side, PNG or JPEG.\\n- Text, in characters after trimming: title 200, generator 100, note text 500, card title 80, card body 300, next label 24, cover title 80, cover body 200, cover button 24, button label 24, end text 200, link 500.\\n- 400 steps in one published tour, and 512,000 bytes for its text (titles, notes, cards and settings together).\\n- One publish request copies up to 12 images; one delete request removes up to 250 files.\\n- 5 open uploads per workspace, unless the server's settings give another number.\\n- An upload that is not finished is removed after 24 hours.\\n- A shared image: 10,485,760 bytes and 8,192 pixels on a side, PNG or JPEG. A shared clip: 52,428,800 bytes, GIF or MP4, at most 8,192 pixels on a side and 10 minutes long. The server's settings can give other numbers for the image and clip sizes. Each is sent in parts of 2,000,000 bytes. An item's preview: 100,000 bytes and 512 pixels on a side, PNG or JPEG. A workspace starts at most 60 items an hour, and an item that is not finished is removed after 24 hours.\\n- A workspace may have a storage allowance, set by the server's settings or its admin. An upload or a shared item that would take the workspace over it is refused when it is started, with 413 `storage_full` and the numbers, before anything is stored. Nothing is ever deleted because of an allowance.\\n- A publish that makes no progress for 15 minutes counts as abandoned.\\n\\nAnything over a limit is refused, never cut short.\"\n  },\n  \"servers\": [\n    {\n      \"url\": \"/\"\n    }\n  ],\n  \"tags\": [\n    {\n      \"name\": \"Tours\",\n      \"description\": \"List, rename, publish, unpublish and delete tours, and read a draft step's image.\"\n    },\n    {\n      \"name\": \"Uploads\",\n      \"description\": \"Send a tour, a new chapter or a chapter's replacement: start, one request per image, finish.\"\n    },\n    {\n      \"name\": \"Items\",\n      \"description\": \"Share a single image or a short clip: start, one request per part, an optional preview, finish; then list, read and delete.\"\n    },\n    {\n      \"name\": \"Workspace\",\n      \"description\": \"The workspace a token or a session belongs to.\"\n    },\n    {\n      \"name\": \"Accounts\",\n      \"description\": \"Signing in with a link sent by mail, the browser sessions of an account, and changing its email address. The site's own pages use these.\"\n    },\n    {\n      \"name\": \"Admin\",\n      \"description\": \"For the site's admin alone: the site's storage in all, how each account uses its storage, and each workspace's allowance. To anyone else these answer 404.\"\n    },\n    {\n      \"name\": \"Server\",\n      \"description\": \"Whether the server is up. Needs no token.\"\n    }\n  ],\n  \"paths\": {\n    \"/api/v1/tours\": {\n      \"get\": {\n        \"tags\": [\n          \"Tours\"\n        ],\n        \"summary\": \"List the workspace's tours\",\n        \"description\": \"Every tour of the token's workspace, drafts and published, most recently changed first. url is the public link as a path, /t/<slug>, to put after the server address; it and published_at are null for a draft.\",\n        \"operationId\": \"listTours\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The tours.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/TourList\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/tours/{id}\": {\n      \"patch\": {\n        \"tags\": [\n          \"Tours\"\n        ],\n        \"summary\": \"Rename a tour\",\n        \"description\": \"Changes the title only. The title follows the rule of a tour's title at upload: trimmed, 1 to 200 characters, no control or format characters. The slug and the public link stay the same. A rename shows on the public page of a published tour at once, without publishing again.\",\n        \"operationId\": \"renameTour\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The tour's id, as the tour list and an upload's commit give it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^tour_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/RenameBody\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The tour's id, and the title as saved.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Renamed\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object. bad_title: the title breaks the rule; the detail says how.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_title\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such tour in this workspace: unknown, another workspace's, or already deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"The request body is too long.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_large\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      },\n      \"delete\": {\n        \"tags\": [\n          \"Tours\"\n        ],\n        \"summary\": \"Delete a tour, in steps\",\n        \"description\": \"Removes the tour, its chapters and steps, its draft images and logo, its published images and any unfinished upload into it. This cannot be undone. A large tour takes several requests, each removing up to 250 files: send the same request until it answers 200. From the first request on, the tour is gone from the list and its public page answers 404; the later requests only remove files. A repeated request after the tour is gone answers 404, so treat 404 as \\\"gone\\\". Delete does not stop a publish in progress: let it finish, or unpublish the tour, then delete.\",\n        \"operationId\": \"deleteTour\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The tour's id, as the tour list and an upload's commit give it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^tour_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Nothing of the tour is left.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Deleted\"\n                }\n              }\n            }\n          },\n          \"202\": {\n            \"description\": \"The tour is deleted; files remain to remove. Send the same request again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/InProgress\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such tour in this workspace: unknown, another workspace's, or already deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"A publish of this tour is in progress. Wait for it to finish, or unpublish the tour to stop it, then delete again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"publish_busy\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"500\": {\n            \"description\": \"The tour is deleted, but some of its files could not be removed yet. Send the same request again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"cleanup_pending\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/tours/{id}/publish\": {\n      \"post\": {\n        \"tags\": [\n          \"Tours\"\n        ],\n        \"summary\": \"Publish a tour, in steps\",\n        \"description\": \"Copies the tour's draft into a public version at its link. Send it with no body to start, or to join the publish already in progress for the current draft. A small tour answers 200 at once. A large one answers 202 with a publish_id: send the request again with that id, each request copying up to 12 images, until it answers 200. Visitors see the previously published version until the last request, and a publish that did not finish never touches it. A publish works from the draft as it was when it started. A tour of more than 400 steps, or one whose text is over 512,000 bytes, answers 413 on the first request, before anything is copied. A publish with no progress for 15 minutes counts as abandoned, and the next request without a publish_id starts a new one.\",\n        \"operationId\": \"publishTour\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The tour's id, as the tour list and an upload's commit give it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^tour_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": false,\n          \"description\": \"Empty to start; the previous answer's publish_id to continue.\",\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/PublishBody\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The new version is live. The same answer on any repeat.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Published\"\n                }\n              }\n            }\n          },\n          \"202\": {\n            \"description\": \"Images are being copied. Send the request again with this publish_id.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/PublishInProgress\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is neither empty nor a publish_id. empty_tour: a tour with no steps cannot be published.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"empty_tour\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such tour in this workspace: unknown, another workspace's, or already deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"publish_cancelled: that publish was stopped before it finished (the tour was unpublished, the publish failed or was abandoned, or a fresh start replaced it); publish again to start over. publish_busy: another publish of the tour is starting at this moment, or its draft changed while this one was starting; nothing was written, try again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"publish_cancelled\",\n                        \"publish_busy\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"The tour has too many steps or too much text to publish, or the request body is too long.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_large\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"500\": {\n            \"description\": \"The tour could not be published. What was published before is unchanged.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"publish_failed\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/tours/{id}/unpublish\": {\n      \"post\": {\n        \"tags\": [\n          \"Tours\"\n        ],\n        \"summary\": \"Unpublish a tour\",\n        \"description\": \"Takes the tour's public page and images down at once and makes the tour a draft again. A publish in progress is cancelled. Removing a large tour's public images can take more than one request: send the same request until it answers 204. Unpublishing a draft answers 204 too.\",\n        \"operationId\": \"unpublishTour\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The tour's id, as the tour list and an upload's commit give it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^tour_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"202\": {\n            \"description\": \"The tour is unpublished; public images remain to remove. Send the same request again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/UnpublishInProgress\"\n                }\n              }\n            }\n          },\n          \"204\": {\n            \"description\": \"The tour is a draft and all its public images are gone.\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such tour in this workspace: unknown, another workspace's, or already deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"500\": {\n            \"description\": \"The tour is unpublished, but some of its public images could not be removed yet. Send the same request again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"cleanup_pending\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/tours/{id}/steps/{step_id}/image\": {\n      \"get\": {\n        \"tags\": [\n          \"Tours\"\n        ],\n        \"summary\": \"Get a draft step's image\",\n        \"description\": \"The picture of one step of the draft, as it was uploaded. The type is the one the server read from the file's own bytes at upload. Nothing may cache it but the client that asked.\",\n        \"operationId\": \"getStepImage\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The tour's id, as the tour list and an upload's commit give it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^tour_[0-9a-f]{24}$\"\n            }\n          },\n          {\n            \"name\": \"step_id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The step's id.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^st_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The image.\",\n            \"headers\": {\n              \"content-security-policy\": {\n                \"description\": \"Always `default-src 'none'; sandbox`, so the picture can do nothing when opened on its own.\",\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"const\": \"default-src 'none'; sandbox\"\n                }\n              },\n              \"cache-control\": {\n                \"description\": \"Always `private, no-store`.\",\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"const\": \"private, no-store\"\n                }\n              }\n            },\n            \"content\": {\n              \"image/png\": {\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"format\": \"binary\"\n                }\n              },\n              \"image/jpeg\": {\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"format\": \"binary\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such step in this workspace.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/uploads\": {\n      \"post\": {\n        \"tags\": [\n          \"Uploads\"\n        ],\n        \"summary\": \"Start an upload\",\n        \"description\": \"Starts an upload from the tour's manifest (at most 262,144 bytes) and says where it goes: a new tour, a new chapter of a tour, or the replacement of a chapter. Then send each step's image, the logo if one is due, and finish the upload; nothing changes in any tour until then. A replace changes the draft only: the public page stays as it was until the tour is published again. A workspace may have 5 open uploads at a time (the server's settings can give another number), and an upload that is not finished is removed after 24 hours. A repeated request only makes another upload. On a workspace with a storage allowance, an upload that would take it over is refused here with 413 storage_full, before any image is sent. A new tour or a new chapter needs room for all its images; the replacement of a chapter needs room only for what its images come to above the chapter's present ones. An upload that carries a logo (a new tour, or the replacement of a tour's first chapter, when the manifest names a logo) also needs room for the logo: logo_bytes when the request gives it, and without logo_bytes up to 200,000 bytes; for a replacement, only what that comes to above the size recorded for the tour's present logo. So a replacement that does not grow the chapter is never refused for storage when it carries no logo, or gives a logo_bytes no larger than the present logo's recorded size.\",\n        \"operationId\": \"createUpload\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/UploadCreate\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"201\": {\n            \"description\": \"The upload exists. For the target replace the answer also has have and settings.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"oneOf\": [\n                    {\n                      \"$ref\": \"#/components/schemas/UploadCreated\"\n                    },\n                    {\n                      \"$ref\": \"#/components/schemas/ReplaceCreated\"\n                    }\n                  ]\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object, or sha256 is not one 64-character lowercase hex text per step, or comes with another target than replace, or logo_bytes is not a whole number from 1 to 200,000. bad_manifest: the manifest breaks a rule; the detail names the field. bad_target: the target is missing or its kind is not new, chapter or replace.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_manifest\",\n                        \"bad_target\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"The target's tour is not in this workspace (detail: no such tour), or the chapter is not a chapter of that tour (detail: no such chapter).\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"too_large: the request body is too long. storage_full: the upload would take the workspace over its storage allowance; nothing was stored, and the answer carries the numbers in bytes. Deleting tours, or a larger allowance, makes room; waiting does not.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"oneOf\": [\n                    {\n                      \"type\": \"object\",\n                      \"required\": [\n                        \"error\",\n                        \"detail\"\n                      ],\n                      \"properties\": {\n                        \"error\": {\n                          \"type\": \"string\",\n                          \"enum\": [\n                            \"too_large\"\n                          ]\n                        },\n                        \"detail\": {\n                          \"type\": \"string\"\n                        }\n                      },\n                      \"additionalProperties\": false\n                    },\n                    {\n                      \"$ref\": \"#/components/schemas/StorageFull\"\n                    }\n                  ]\n                }\n              }\n            }\n          },\n          \"429\": {\n            \"description\": \"The workspace already has its number of open uploads. Finish or cancel one first.\",\n            \"headers\": {\n              \"retry-after\": {\n                \"description\": \"Seconds to wait before trying again.\",\n                \"schema\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 1\n                }\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_many_uploads\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/uploads/{id}/steps/{n}\": {\n      \"put\": {\n        \"tags\": [\n          \"Uploads\"\n        ],\n        \"summary\": \"Send one step's image\",\n        \"description\": \"The body is the image itself, a PNG or a JPEG of at most 2,000,000 bytes and 4,096 pixels on a side. Its type, width, height and length must be exactly what the manifest gives for the step; the server reads them from the file's own bytes, not from the Content-Type. Steps may be sent in any order, each once.\",\n        \"operationId\": \"putStepImage\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The upload's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^up_[0-9a-f]{24}$\"\n            }\n          },\n          {\n            \"name\": \"n\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The step's number in the manifest, counted from 1.\",\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 200\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"image/png\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            },\n            \"image/jpeg\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"204\": {\n            \"description\": \"The image is stored.\"\n          },\n          \"400\": {\n            \"description\": \"The body is not the image the manifest describes; the detail says what differs.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_image\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such upload in this workspace: unknown, another workspace's, finished or cancelled, or the manifest has no step of that number.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"This step was already sent, or the chapter already has its image (a step listed in have).\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"already_sent\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"The image is too long.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_large\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/uploads/{id}/logo\": {\n      \"put\": {\n        \"tags\": [\n          \"Uploads\"\n        ],\n        \"summary\": \"Send the logo\",\n        \"description\": \"The body is the cover's logo, a PNG or a JPEG (as the manifest's cover names it) of at most 200,000 bytes and 512 pixels on a side. Only an upload that makes a new tour, or replaces a tour's first chapter, takes a logo; a tour keeps its logo otherwise. When the upload was started with logo_bytes, the logo must have exactly that length.\",\n        \"operationId\": \"putLogo\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The upload's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^up_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"image/png\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            },\n            \"image/jpeg\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"204\": {\n            \"description\": \"The logo is stored.\"\n          },\n          \"400\": {\n            \"description\": \"The body is not a logo of the type the manifest names, or is too large on a side, or its length differs from the logo_bytes the upload was started with.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_image\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such upload in this workspace: unknown, another workspace's, finished or cancelled, or its manifest names no logo.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"logo_not_used: this upload goes into an existing tour, which keeps its logo; do not send one. already_sent: the logo was already sent.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"logo_not_used\",\n                        \"already_sent\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"The logo is too long.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_large\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/uploads/{id}/commit\": {\n      \"post\": {\n        \"tags\": [\n          \"Uploads\"\n        ],\n        \"summary\": \"Finish an upload\",\n        \"description\": \"Puts the upload into the draft in one go: a new tour, a new chapter, or the chapter with exactly the manifest's steps. Nothing is public until the tour is published. A repeated request answers 201 with the same ids. For a replace the answer's publish says what publishing would do now: draft, ready or other_changes.\",\n        \"operationId\": \"commitUpload\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The upload's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^up_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"201\": {\n            \"description\": \"The draft holds the upload. For the target replace the answer also has publish.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"oneOf\": [\n                    {\n                      \"$ref\": \"#/components/schemas/Committed\"\n                    },\n                    {\n                      \"$ref\": \"#/components/schemas/ReplaceCommitted\"\n                    }\n                  ]\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such upload in this workspace: unknown, another workspace's, finished or cancelled.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"incomplete: a step's image, or a logo the upload must carry, has not been sent; nothing changes. chapter_changed: another upload replaced the chapter since this one started; nothing changes: cancel this upload and start again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"incomplete\",\n                        \"chapter_changed\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/uploads/{id}\": {\n      \"delete\": {\n        \"tags\": [\n          \"Uploads\"\n        ],\n        \"summary\": \"Cancel an upload\",\n        \"description\": \"Removes the upload and only what it stored, never an image a chapter uses. It answers 204 also for an upload that is unknown, finished or already cancelled.\",\n        \"operationId\": \"cancelUpload\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The upload's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^up_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"204\": {\n            \"description\": \"The upload is gone, or was not there.\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/media\": {\n      \"post\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Start a shared item\",\n        \"description\": \"Starts sharing one image (a PNG or a JPEG) or one clip (a GIF or an MP4): say what it is, then send its parts, optionally a preview, and finish it. The answer says how many parts to send; every part but the last is 2,000,000 bytes. On a workspace with a storage allowance, an item that would take it over is refused here with 413 storage_full, before any part is sent; from here on its bytes count as used until it is deleted. An item that is not finished is removed after 24 hours. A workspace starts at most 60 items an hour.\",\n        \"operationId\": \"createMedia\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/MediaCreate\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"201\": {\n            \"description\": \"The item exists. Send its parts.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/MediaCreated\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"The body is not a JSON object, or a field breaks its rule; the detail names it.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"413\": {\n            \"description\": \"too_large: the request body is too long. media_too_large: the item is larger than this server takes, and the answer carries the limits. storage_full: the item would take the workspace over its storage allowance; nothing was stored. Deleting tours or items, or a larger allowance, makes room.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"oneOf\": [\n                    {\n                      \"type\": \"object\",\n                      \"required\": [\n                        \"error\",\n                        \"detail\"\n                      ],\n                      \"properties\": {\n                        \"error\": {\n                          \"type\": \"string\",\n                          \"enum\": [\n                            \"too_large\"\n                          ]\n                        },\n                        \"detail\": {\n                          \"type\": \"string\"\n                        }\n                      },\n                      \"additionalProperties\": false\n                    },\n                    {\n                      \"$ref\": \"#/components/schemas/MediaTooLarge\"\n                    },\n                    {\n                      \"$ref\": \"#/components/schemas/StorageFull\"\n                    }\n                  ]\n                }\n              }\n            }\n          },\n          \"429\": {\n            \"description\": \"This workspace already started 60 items in the last hour.\",\n            \"headers\": {\n              \"retry-after\": {\n                \"description\": \"Seconds until the count starts again.\",\n                \"schema\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 1\n                }\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_many_items\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      },\n      \"get\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"List the workspace's shared items\",\n        \"description\": \"The finished items of the workspace of one kind, newest first, 50 at a time. Ask with the query kind=image or kind=clip; for the next page add cursor= with the next of the previous answer. Items that are not finished are not listed.\",\n        \"operationId\": \"listMedia\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"One page of items.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/MediaList\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: kind is missing or not image or clip. bad_cursor: the cursor is not one this list gave.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_cursor\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/media/{id}\": {\n      \"get\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Get one shared item\",\n        \"description\": \"One item of the workspace, finished or not, with its state.\",\n        \"operationId\": \"getMedia\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The item's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^med_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The item.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/MediaItemState\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such item in this workspace: unknown, another workspace's, or being deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      },\n      \"delete\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Delete a shared item\",\n        \"description\": \"Removes an item, finished or not, with every part and its preview. Its bytes stop counting at once, and its public address stops working. When some files could not be removed yet, the answer is 500 cleanup_pending: send the same request again.\",\n        \"operationId\": \"deleteMedia\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The item's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^med_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"204\": {\n            \"description\": \"Nothing of the item is left.\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such item in this workspace: unknown, another workspace's, or being deleted, or already deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"500\": {\n            \"description\": \"The item is deleted, but some of its files could not be removed yet. Send the same request again.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"cleanup_pending\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/media/{id}/parts/{n}\": {\n      \"put\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Send one part of an item\",\n        \"description\": \"The body is part n of the file, as bytes: 2,000,000 bytes for every part but the last, which holds the rest. Part 0 must start like a file of the declared type, read from its own bytes, and for a PNG, JPEG or GIF its width and height must be the declared ones; an MP4's size and duration are taken as declared. Parts may be sent in any order; sending one again replaces it.\",\n        \"operationId\": \"putMediaPart\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The item's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^med_[0-9a-f]{24}$\"\n            }\n          },\n          {\n            \"name\": \"n\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The part's number, counted from 0.\",\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 0,\n              \"maximum\": 998\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/octet-stream\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"204\": {\n            \"description\": \"The part is stored.\"\n          },\n          \"400\": {\n            \"description\": \"bad_part: the part's length is not the one it must have. bad_media: part 0 is not a file of the declared type, or its width and height differ from the declared ones.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_part\",\n                        \"bad_media\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such item in this workspace: unknown, another workspace's, or being deleted, or the item has no part of that number.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"The item is finished; its parts cannot change.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"already_online\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"The part is too long.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"too_large\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/media/{id}/preview\": {\n      \"put\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Send an item's preview\",\n        \"description\": \"Optional: a small picture that stands for the item in lists, a PNG or a JPEG of at most 100,000 bytes and 512 pixels on a side, read from its own bytes. Send it before the item is finished; a new one replaces the old. Its size counts against the storage allowance.\",\n        \"operationId\": \"putMediaPreview\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The item's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^med_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"image/png\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            },\n            \"image/jpeg\": {\n              \"schema\": {\n                \"type\": \"string\",\n                \"format\": \"binary\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"204\": {\n            \"description\": \"The preview is stored.\"\n          },\n          \"400\": {\n            \"description\": \"The body is not a PNG or JPEG within the preview's size.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_image\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such item in this workspace: unknown, another workspace's, or being deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"The item is finished; its preview cannot change.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"already_online\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"413\": {\n            \"description\": \"too_large: the preview is too long. storage_full: it would take the workspace over its storage allowance; nothing was stored.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"oneOf\": [\n                    {\n                      \"type\": \"object\",\n                      \"required\": [\n                        \"error\",\n                        \"detail\"\n                      ],\n                      \"properties\": {\n                        \"error\": {\n                          \"type\": \"string\",\n                          \"enum\": [\n                            \"too_large\"\n                          ]\n                        },\n                        \"detail\": {\n                          \"type\": \"string\"\n                        }\n                      },\n                      \"additionalProperties\": false\n                    },\n                    {\n                      \"$ref\": \"#/components/schemas/StorageFull\"\n                    }\n                  ]\n                }\n              }\n            }\n          }\n        }\n      },\n      \"get\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Get an item's preview\",\n        \"description\": \"The item's preview picture, to its own workspace, as the type read from its bytes when it was sent.\",\n        \"operationId\": \"getMediaPreview\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The item's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^med_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The preview.\",\n            \"content\": {\n              \"image/png\": {\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"format\": \"binary\"\n                }\n              },\n              \"image/jpeg\": {\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"format\": \"binary\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such item in this workspace: unknown, another workspace's, or being deleted, or it has no preview.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/media/{id}/commit\": {\n      \"post\": {\n        \"tags\": [\n          \"Items\"\n        ],\n        \"summary\": \"Finish a shared item\",\n        \"description\": \"Checks that every part is stored and that they add up to the declared bytes, and puts the item online at its public address. From then on it does not change until it is deleted. A repeated request answers the same.\",\n        \"operationId\": \"commitMedia\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The item's id, from the answer that started it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^med_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The item is online.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/MediaCommitted\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such item in this workspace: unknown, another workspace's, or being deleted.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"409\": {\n            \"description\": \"A part has not been sent or is still being sent, the parts do not add up to the declared bytes, or the preview is still being sent; the detail says which. Nothing changes.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"incomplete\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/me\": {\n      \"get\": {\n        \"tags\": [\n          \"Workspace\"\n        ],\n        \"summary\": \"The workspace and the server version\",\n        \"description\": \"The name of the token's workspace and the version of the server: the request to test a connection with. On a server with two addresses the answer also has addresses, the two host names.\",\n        \"operationId\": \"getMe\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The workspace and the version.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Me\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"The token's workspace no longer exists.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/usage\": {\n      \"get\": {\n        \"tags\": [\n          \"Workspace\"\n        ],\n        \"summary\": \"The workspace's storage use\",\n        \"description\": \"What the token's workspace uses of its storage allowance, in bytes. Counted: the image of every step of every tour, published or not; each tour's logo; and the room held by every upload that is not finished (its images as the manifest gives them, and for a logo it carries the logo_bytes it was started with, or 200,000 bytes without, until the logo's real size is recorded when the upload is finished), until the upload is finished, cancelled or removed. An upload nobody finishes is not removed by the clock alone: it is removed when the workspace next starts an upload once it is more than 24 hours old, and until then its room is still counted here. Not counted: the copies of images a published tour serves, and files that wait to be removed after a delete or a replace. allowance_bytes is null when neither the server's settings nor the workspace has one: No limit. over is true when more is used than the allowance, which can happen when an allowance is lowered; the server never deletes or unpublishes anything because of it, and only starting an upload that needs room is refused.\",\n        \"operationId\": \"getUsage\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The workspace's numbers.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Usage\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/usage/largest\": {\n      \"get\": {\n        \"tags\": [\n          \"Workspace\"\n        ],\n        \"summary\": \"The workspace's ten largest tours\",\n        \"description\": \"The 10 largest tours of the token's workspace, largest first, each with its id, its title and its size in bytes as the tour list gives it (its steps' images and its logo, as GET /api/v1/usage counts them). Tours of the same size come in the order of their id. Fewer when the workspace has fewer tours; none for an empty one.\",\n        \"operationId\": \"getLargestTours\",\n        \"security\": [\n          {\n            \"token\": []\n          },\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The largest tours.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/LargestTours\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/signin/request\": {\n      \"post\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"Ask for a sign-in link\",\n        \"description\": \"Mails a sign-in link to the address, when it belongs to an account that may sign in, the site has an admin and mail is on. The answer is the same in every case, so it does not tell whether the address has an account, and it does not wait for the mail. The link works once and for 15 minutes. Needs no credential, but must come from a page of the address it is sent to, as JSON. One address gets at most a few links in a quarter hour and in a day; past that the answer is the same and no mail is sent.\",\n        \"operationId\": \"requestSignInLink\",\n        \"security\": [],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/SignInRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The same for every well-formed address.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Ok\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object sent as application/json. bad_email, with no detail: email is not an email address.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_email\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"403\": {\n            \"description\": \"The request did not come from a page of this address: no Origin, another one, or the browser says it came from another site.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_origin\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"429\": {\n            \"description\": \"Too many requests from this network. Nothing was sent.\",\n            \"headers\": {\n              \"retry-after\": {\n                \"description\": \"Seconds until the count starts again.\",\n                \"schema\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 1\n                }\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"rate_limited\"\n                      ]\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/signin/complete\": {\n      \"post\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"Finish signing in\",\n        \"description\": \"Turns the code of a sign-in link into a session, once, and sets the session cookie on this address. A session the browser already had ends. Needs no credential, but must come from a page of the address it is sent to, as JSON. A code that is unknown, already used, expired or of an account that may not sign in gets the one answer link_invalid. The answer never repeats the code.\",\n        \"operationId\": \"completeSignIn\",\n        \"security\": [],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/SignInComplete\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Signed in.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Ok\"\n                }\n              }\n            },\n            \"headers\": {\n              \"set-cookie\": {\n                \"description\": \"The session cookie: host-only, Secure, HttpOnly and SameSite=Lax.\",\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^__Host-dp_session=\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object sent as application/json. bad_code, with no detail: code is not a sign-in code.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_code\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"403\": {\n            \"description\": \"bad_origin: the request did not come from a page of this address. link_invalid: the link has expired or was already used; ask for a new one.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_origin\",\n                        \"link_invalid\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"429\": {\n            \"description\": \"Too many tries from this network. Nothing was looked at.\",\n            \"headers\": {\n              \"retry-after\": {\n                \"description\": \"Seconds until the count starts again.\",\n                \"schema\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 1\n                }\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"rate_limited\"\n                      ]\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/session\": {\n      \"get\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"The session and who it is\",\n        \"description\": \"The account, its workspace and this session, and the anti-forgery value a change made with the session needs. Sets the session cookie again. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"getSession\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The session.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Session\"\n                }\n              }\n            },\n            \"headers\": {\n              \"set-cookie\": {\n                \"description\": \"The same session cookie again.\",\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^__Host-dp_session=\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/sessions\": {\n      \"get\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"List the account's sessions\",\n        \"description\": \"Every live session of the caller's own account, where it is signed in, with the current one first and marked. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"listSessions\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The sessions.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/SessionList\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/sessions/{id}\": {\n      \"delete\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"End one of the account's sessions\",\n        \"description\": \"Ends one session of the caller's own account, such as one in another browser; the cookie is not touched. Another account's session answers 404, the same as one that does not exist. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"endSession\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The session's id, as the list of sessions gives it.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^ses_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"204\": {\n            \"description\": \"The session has ended.\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"404\": {\n            \"description\": \"No such live session of this account.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/signout\": {\n      \"post\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"Sign out\",\n        \"description\": \"Ends the session the request is sent with and clears its cookie. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"signOut\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"204\": {\n            \"description\": \"Signed out.\",\n            \"headers\": {\n              \"set-cookie\": {\n                \"description\": \"Clears the session cookie.\",\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^__Host-dp_session=\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/signout/everywhere\": {\n      \"post\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"Sign out everywhere\",\n        \"description\": \"Ends every session of the caller's account, in every browser, and clears this one's cookie. Tokens keep working. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"signOutEverywhere\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"204\": {\n            \"description\": \"Every session of the account has ended.\",\n            \"headers\": {\n              \"set-cookie\": {\n                \"description\": \"Clears the session cookie.\",\n                \"schema\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^__Host-dp_session=\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          }\n        }\n      }\n    },\n    \"/api/v1/account/email\": {\n      \"post\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"Ask to change the email address\",\n        \"description\": \"Mails a link to the new address; the account's address changes only when that link is opened (POST /api/v1/account/email/confirm), once and within 15 minutes. Asking again replaces the earlier link. The answer is the same whether the new address is free, belongs to another account or is the account's own, so it does not tell who has an account; only a free address is sent a link, and no other mail is sent. It does not wait for the mail. Each account, each account for one address, and each address from all accounts together, can be asked for only a few times in a quarter hour and in a day; an account that asks too often for one address limits only itself, not others asking for it. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"requestEmailChange\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/EmailChangeRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The same for every well-formed address.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Ok\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object sent as application/json. bad_email, with no detail: email is not an email address.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_email\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"409\": {\n            \"description\": \"This site cannot send mail, so the address cannot be changed here. Nothing was stored.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"mail_off\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"429\": {\n            \"description\": \"Too many requests for this account or this address. Nothing was stored or sent.\",\n            \"headers\": {\n              \"retry-after\": {\n                \"description\": \"Seconds until the count starts again.\",\n                \"schema\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 1\n                }\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"rate_limited\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/account/email/confirm\": {\n      \"post\": {\n        \"tags\": [\n          \"Accounts\"\n        ],\n        \"summary\": \"Finish changing the email address\",\n        \"description\": \"Makes the change the code of the link names, once: the account's address becomes the new one, its open sign-in links stop working, and the old address is sent a notice that shows the new one partly hidden. It must be sent with a session of the account that asked. The account stays signed in everywhere. A code that is unknown, already used, more than 15 minutes old, replaced by a later request or of another account, and one for an address another account has taken since, all get the one answer bad_code. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"confirmEmailChange\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/EmailChangeConfirm\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The address was changed.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/EmailChanged\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object sent as application/json. bad_code: the link no longer works; ask for a new one.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_code\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Unauthorized\"\n          },\n          \"429\": {\n            \"description\": \"Too many tries for this account. Nothing was looked at.\",\n            \"headers\": {\n              \"retry-after\": {\n                \"description\": \"Seconds until the count starts again.\",\n                \"schema\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 1\n                }\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"rate_limited\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/admin/summary\": {\n      \"get\": {\n        \"tags\": [\n          \"Admin\"\n        ],\n        \"summary\": \"Every account's storage use in all\",\n        \"description\": \"For the site's admin: how many accounts there are, what all their workspaces use together (counted as GET /api/v1/usage counts it for each account itself) and the site's standard allowance, null when the server's settings set none. Nothing of any workspace is in it. Every refusal is the one 404, whoever asks and whatever is wrong with the request. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"adminSummary\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The three numbers.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/AdminSummary\"\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"description\": \"Anything other than the site's admin, signed in on this address, with a correct request: no credential, a token, another account's session, a token with a session, or a session on the tours address. The 400 and 403 answers any request can get are this 404 here.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/admin/accounts\": {\n      \"get\": {\n        \"tags\": [\n          \"Admin\"\n        ],\n        \"summary\": \"List every account's storage use\",\n        \"description\": \"For the site's admin: every account, in the order they were made, 100 at a time, with its workspace's id and name, its tour count, what it uses of its storage (counted as GET /api/v1/usage counts it for the account itself) and its allowance. Nothing of any workspace's tours is in it. Add ?after=<id>, with the next of the previous answer, for the next page. Every refusal is the one 404, whoever asks and whatever is wrong with the request. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"adminListAccounts\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The accounts.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/AdminAccountList\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"after is not the id of an account.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"description\": \"Anything other than the site's admin, signed in on this address, with a correct request: no credential, a token, another account's session, a token with a session, or a session on the tours address. The 400 and 403 answers any request can get are this 404 here.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/api/v1/admin/workspaces/{id}\": {\n      \"patch\": {\n        \"tags\": [\n          \"Admin\"\n        ],\n        \"summary\": \"Set a workspace's storage allowance\",\n        \"description\": \"For the site's admin: sets the workspace's storage allowance in bytes, or with null goes back to the site's default (the server's setting). The change is in the audit record with the old and the new number. An allowance below what the workspace already uses is taken: nothing is deleted or unpublished, and only starting an upload that needs more room is refused from then on. Every refusal of the caller or of the request's origin, and a workspace that does not exist, is the one 404. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\",\n        \"operationId\": \"adminSetAllowance\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"The workspace's id, as the list of accounts gives it in workspace_id.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"pattern\": \"^ws_[0-9a-f]{24}$\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/AllowanceChange\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The workspace's numbers after the change.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/AllowanceSet\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"bad_request: the body is not a JSON object holding storage_allowance_bytes and nothing else. bad_allowance: the value is not a whole number of bytes from 0 to 9007199254740991, or null for the site's default.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\",\n                    \"detail\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"bad_request\",\n                        \"bad_allowance\"\n                      ]\n                    },\n                    \"detail\": {\n                      \"type\": \"string\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"description\": \"No such workspace, or anything other than the site's admin, signed in on this address, with a correct request: no credential, a token, another account's session, a token with a session, a session on the tours address, a change from another origin or without the anti-forgery header. The 400 and 403 answers any request can get are this 404 here.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"error\"\n                  ],\n                  \"properties\": {\n                    \"error\": {\n                      \"type\": \"string\",\n                      \"enum\": [\n                        \"not_found\"\n                      ]\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/healthz\": {\n      \"get\": {\n        \"tags\": [\n          \"Server\"\n        ],\n        \"summary\": \"Whether the server is up\",\n        \"description\": \"Answers 200 when the server runs and reaches its database. It needs no token and answers on every host name. On a server with two addresses, asked on one of them, it also says which of the two it was reached on.\",\n        \"operationId\": \"getHealth\",\n        \"security\": [],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The server is up.\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Health\"\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n  },\n  \"components\": {\n    \"securitySchemes\": {\n      \"token\": {\n        \"type\": \"http\",\n        \"scheme\": \"bearer\"\n      },\n      \"session\": {\n        \"type\": \"apiKey\",\n        \"in\": \"cookie\",\n        \"name\": \"__Host-dp_session\"\n      }\n    },\n    \"schemas\": {\n      \"Error\": {\n        \"type\": \"object\",\n        \"description\": \"The shape of every refusal. Each request lists the codes it can answer.\",\n        \"required\": [\n          \"error\"\n        ],\n        \"properties\": {\n          \"error\": {\n            \"type\": \"string\",\n            \"description\": \"A stable code, such as not_found.\"\n          },\n          \"detail\": {\n            \"type\": \"string\",\n            \"description\": \"The reason in plain words. The text may change; do not match on it.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Unauthorized\": {\n        \"type\": \"object\",\n        \"description\": \"The one answer for a missing, malformed, unknown, expired or revoked token or session.\",\n        \"required\": [\n          \"error\"\n        ],\n        \"properties\": {\n          \"error\": {\n            \"type\": \"string\",\n            \"const\": \"unauthorized\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"InProgress\": {\n        \"type\": \"object\",\n        \"description\": \"A delete that has more to do. Send the same request again.\",\n        \"required\": [\n          \"status\",\n          \"done\",\n          \"total\"\n        ],\n        \"properties\": {\n          \"status\": {\n            \"type\": \"string\",\n            \"const\": \"in_progress\"\n          },\n          \"done\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"Files removed so far.\"\n          },\n          \"total\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"Files to remove in all.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"PublishInProgress\": {\n        \"type\": \"object\",\n        \"description\": \"A publish that has more images to copy.\",\n        \"required\": [\n          \"status\",\n          \"publish_id\",\n          \"done\",\n          \"total\"\n        ],\n        \"properties\": {\n          \"status\": {\n            \"type\": \"string\",\n            \"const\": \"in_progress\"\n          },\n          \"publish_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^pub_[0-9a-f]{24}$\",\n            \"description\": \"Send it back in the next publish request to continue this publish.\"\n          },\n          \"done\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"Images copied so far.\"\n          },\n          \"total\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"Images to copy in all.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"UnpublishInProgress\": {\n        \"type\": \"object\",\n        \"description\": \"The tour is unpublished, but some of its public images are still to be removed. Send the same request again.\",\n        \"required\": [\n          \"status\",\n          \"detail\"\n        ],\n        \"properties\": {\n          \"status\": {\n            \"type\": \"string\",\n            \"const\": \"in_progress\"\n          },\n          \"detail\": {\n            \"type\": \"string\",\n            \"description\": \"What is left to do, in plain words.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Tour\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"title\",\n          \"status\",\n          \"slug\",\n          \"url\",\n          \"chapters\",\n          \"steps\",\n          \"bytes\",\n          \"updated_at\",\n          \"published_at\",\n          \"unpublished_changes\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^tour_[0-9a-f]{24}$\"\n          },\n          \"title\": {\n            \"type\": \"string\"\n          },\n          \"status\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"draft\",\n              \"published\"\n            ]\n          },\n          \"slug\": {\n            \"type\": \"string\",\n            \"description\": \"The last part of the public link. It never changes, also not on a rename.\"\n          },\n          \"url\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"The public link as a path, /t/<slug>, to put after the server address. null for a draft.\"\n          },\n          \"chapters\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many chapters the draft has.\"\n          },\n          \"steps\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many steps the draft has.\"\n          },\n          \"bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"The tour's size in bytes, counted as GET /api/v1/usage counts storage: the images of all its steps and its logo (a logo stored by a server before version 0.1.8 counts as 0). Over all of a workspace's tours these add up to the usage's pictures and logos; uploads that are not finished belong to no tour and are not in it.\"\n          },\n          \"updated_at\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"When the draft last changed, in milliseconds since 1970.\"\n          },\n          \"published_at\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"When the tour was last published, in milliseconds since 1970. null for a draft.\"\n          },\n          \"unpublished_changes\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when the tour is published and its draft holds a chapter upload or update that is not on the public page yet, so publishing it again would change what visitors see; also when the server cannot tell, which happens only for some tours last published before version 0.1.4. false for a draft, and for a published tour whose page is up to date. A rename is live at once and never sets it.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"TourList\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"tours\"\n        ],\n        \"properties\": {\n          \"tours\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"$ref\": \"#/components/schemas/Tour\"\n            },\n            \"description\": \"Most recently changed first.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"RenameBody\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"title\"\n        ],\n        \"properties\": {\n          \"title\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 200,\n            \"description\": \"The new title: trimmed, no control or format characters.\"\n          }\n        }\n      },\n      \"Renamed\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"title\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\"\n          },\n          \"title\": {\n            \"type\": \"string\",\n            \"description\": \"The title as saved (trimmed).\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Deleted\": {\n        \"type\": \"object\",\n        \"description\": \"Nothing of the tour is left.\",\n        \"required\": [\n          \"deleted\"\n        ],\n        \"properties\": {\n          \"deleted\": {\n            \"type\": \"boolean\",\n            \"const\": true\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"PublishBody\": {\n        \"type\": \"object\",\n        \"required\": [],\n        \"properties\": {\n          \"publish_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"pattern\": \"^pub_[0-9a-f]{24}$\",\n            \"description\": \"The publish_id of the previous answer, to continue that publish.\"\n          }\n        }\n      },\n      \"Published\": {\n        \"type\": \"object\",\n        \"description\": \"The new version is live.\",\n        \"required\": [\n          \"slug\",\n          \"url\",\n          \"steps\"\n        ],\n        \"properties\": {\n          \"slug\": {\n            \"type\": \"string\"\n          },\n          \"url\": {\n            \"type\": \"string\",\n            \"description\": \"The tour's link as a path, /t/<slug>, to put after the server address.\"\n          },\n          \"steps\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many steps the published version has.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Me\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"workspace\",\n          \"version\"\n        ],\n        \"properties\": {\n          \"workspace\": {\n            \"type\": \"string\",\n            \"description\": \"The workspace's name.\"\n          },\n          \"version\": {\n            \"type\": \"string\",\n            \"description\": \"The server's version.\"\n          },\n          \"addresses\": {\n            \"type\": \"object\",\n            \"description\": \"Only on a server with two addresses: both host names, without a scheme. Absent means: use the address you were given.\",\n            \"required\": [\n              \"tours\",\n              \"app\"\n            ],\n            \"properties\": {\n              \"tours\": {\n                \"type\": \"string\",\n                \"description\": \"The host name tour links use.\"\n              },\n              \"app\": {\n                \"type\": \"string\",\n                \"description\": \"The host name of the app address.\"\n              }\n            },\n            \"additionalProperties\": false\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Usage\": {\n        \"type\": \"object\",\n        \"description\": \"What a workspace uses of its storage allowance.\",\n        \"required\": [\n          \"used_bytes\",\n          \"allowance_bytes\",\n          \"over\",\n          \"tours\",\n          \"counted\"\n        ],\n        \"properties\": {\n          \"used_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"What the workspace uses, in bytes: the three numbers of counted together.\"\n          },\n          \"allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"The workspace's storage allowance in bytes: its own number, else the server's setting. null when there is no limit.\"\n          },\n          \"over\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when more is used than the allowance. Always false without a limit; exactly the allowance is not over it.\"\n          },\n          \"tours\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many tours the workspace has, drafts and published.\"\n          },\n          \"counted\": {\n            \"type\": \"object\",\n            \"description\": \"What used_bytes is made of, in bytes.\",\n            \"required\": [\n              \"pictures\",\n              \"logos\",\n              \"uploads_in_progress\"\n            ],\n            \"properties\": {\n              \"pictures\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"The images of every step of every tour, published or not.\"\n              },\n              \"logos\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"The tours' logos. A logo stored by a server before version 0.1.8 counts as 0.\"\n              },\n              \"uploads_in_progress\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"The room held by uploads that are not finished: what each one needed when it was started.\"\n              }\n            },\n            \"additionalProperties\": false\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"LargestTours\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"tours\"\n        ],\n        \"properties\": {\n          \"tours\": {\n            \"type\": \"array\",\n            \"maxItems\": 10,\n            \"description\": \"At most 10, largest first; tours of the same size in the order of their ids.\",\n            \"items\": {\n              \"type\": \"object\",\n              \"required\": [\n                \"id\",\n                \"title\",\n                \"bytes\"\n              ],\n              \"properties\": {\n                \"id\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^tour_[0-9a-f]{24}$\"\n                },\n                \"title\": {\n                  \"type\": \"string\"\n                },\n                \"bytes\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 0,\n                  \"description\": \"The tour's size in bytes, as the tour list gives it.\"\n                }\n              },\n              \"additionalProperties\": false\n            }\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"StorageFull\": {\n        \"type\": \"object\",\n        \"description\": \"The upload, shared item or preview would take the workspace over its storage allowance. Nothing was stored, and no upload or item exists that this request made.\",\n        \"required\": [\n          \"error\",\n          \"detail\",\n          \"used_bytes\",\n          \"allowance_bytes\",\n          \"needed_bytes\"\n        ],\n        \"properties\": {\n          \"error\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"storage_full\"\n            ]\n          },\n          \"detail\": {\n            \"type\": \"string\",\n            \"description\": \"The same in words, as one sentence under 200 characters that a program can show after its own words, such as \\\"Could not start the upload: \\\". The text may change; do not match on it.\"\n          },\n          \"used_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"What the workspace uses now, in bytes.\"\n          },\n          \"allowance_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"The workspace's storage allowance, in bytes.\"\n          },\n          \"needed_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"The room this upload needs, in bytes: all its images, and for a logo it carries its logo_bytes, or 200,000 without one; for the replacement of a chapter, only what that comes to above the chapter's present images and, for a tour's first chapter, the recorded size of its present logo. For a shared item, its bytes; for an item's preview, what its size comes to above the preview it replaces.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"MediaCreate\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"kind\",\n          \"content_type\",\n          \"bytes\",\n          \"width\",\n          \"height\"\n        ],\n        \"properties\": {\n          \"kind\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image\",\n              \"clip\"\n            ],\n            \"description\": \"An image (a PNG or a JPEG) or a clip (a GIF or an MP4).\"\n          },\n          \"content_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image/png\",\n              \"image/jpeg\",\n              \"image/gif\",\n              \"video/mp4\"\n            ],\n            \"description\": \"image/png or image/jpeg for an image, image/gif or video/mp4 for a clip. Part 0 must be a file of this type.\"\n          },\n          \"bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"The file's length in bytes: at most 10,485,760 for an image and 52,428,800 for a clip, unless the server's settings give other numbers.\"\n          },\n          \"width\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"In pixels: at most 8,192 for an image, unless the server's settings give another number, and 8,192 for a clip. For a PNG, JPEG or GIF it must be what the file says.\"\n          },\n          \"height\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"In pixels, as width.\"\n          },\n          \"duration_ms\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"maximum\": 600000,\n            \"description\": \"How long the clip runs, in milliseconds. Required for a clip; leave it out for an image. Shown as given.\"\n          },\n          \"title\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"maxLength\": 120,\n            \"description\": \"Optional: at most 120 characters after trimming, no control or format characters. Empty is no title.\"\n          }\n        }\n      },\n      \"MediaCreated\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"parts\",\n          \"part_bytes\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^med_[0-9a-f]{24}$\"\n          },\n          \"parts\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"How many parts to send, numbered from 0.\"\n          },\n          \"part_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"The length of every part but the last, which holds the rest: 2,000,000.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"MediaCommitted\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"link_id\",\n          \"kind\",\n          \"path\",\n          \"link\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^med_[0-9a-f]{24}$\"\n          },\n          \"link_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^[a-z2-7]{20}$\",\n            \"description\": \"The item's public name. It never changes.\"\n          },\n          \"kind\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image\",\n              \"clip\"\n            ]\n          },\n          \"path\": {\n            \"type\": \"string\",\n            \"description\": \"The item's public address as a path: /i/<link_id> for an image, /r/<link_id> for a clip.\"\n          },\n          \"link\": {\n            \"type\": \"string\",\n            \"description\": \"The item's public address in full.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"MediaItem\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"link_id\",\n          \"kind\",\n          \"title\",\n          \"content_type\",\n          \"bytes\",\n          \"width\",\n          \"height\",\n          \"duration_ms\",\n          \"created_at\",\n          \"has_preview\",\n          \"path\",\n          \"link\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^med_[0-9a-f]{24}$\"\n          },\n          \"link_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^[a-z2-7]{20}$\"\n          },\n          \"kind\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image\",\n              \"clip\"\n            ]\n          },\n          \"title\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ]\n          },\n          \"content_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image/png\",\n              \"image/jpeg\",\n              \"image/gif\",\n              \"video/mp4\"\n            ]\n          },\n          \"bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"The file's length in bytes.\"\n          },\n          \"width\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"In pixels.\"\n          },\n          \"height\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"In pixels.\"\n          },\n          \"duration_ms\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"A clip's duration in milliseconds, as given. null for an image.\"\n          },\n          \"created_at\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"When the item was started, in milliseconds since 1970.\"\n          },\n          \"has_preview\": {\n            \"type\": \"boolean\",\n            \"description\": \"Whether a preview picture was sent.\"\n          },\n          \"path\": {\n            \"type\": \"string\",\n            \"description\": \"The public address as a path: /i/<link_id> or /r/<link_id>.\"\n          },\n          \"link\": {\n            \"type\": \"string\",\n            \"description\": \"The public address in full.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"MediaItemState\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"link_id\",\n          \"kind\",\n          \"title\",\n          \"content_type\",\n          \"bytes\",\n          \"width\",\n          \"height\",\n          \"duration_ms\",\n          \"created_at\",\n          \"has_preview\",\n          \"path\",\n          \"link\",\n          \"state\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^med_[0-9a-f]{24}$\"\n          },\n          \"link_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^[a-z2-7]{20}$\"\n          },\n          \"kind\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image\",\n              \"clip\"\n            ]\n          },\n          \"title\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ]\n          },\n          \"content_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"image/png\",\n              \"image/jpeg\",\n              \"image/gif\",\n              \"video/mp4\"\n            ]\n          },\n          \"bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"The file's length in bytes.\"\n          },\n          \"width\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"In pixels.\"\n          },\n          \"height\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"In pixels.\"\n          },\n          \"duration_ms\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"A clip's duration in milliseconds, as given. null for an image.\"\n          },\n          \"created_at\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"When the item was started, in milliseconds since 1970.\"\n          },\n          \"has_preview\": {\n            \"type\": \"boolean\",\n            \"description\": \"Whether a preview picture was sent.\"\n          },\n          \"path\": {\n            \"type\": \"string\",\n            \"description\": \"The public address as a path: /i/<link_id> or /r/<link_id>.\"\n          },\n          \"link\": {\n            \"type\": \"string\",\n            \"description\": \"The public address in full.\"\n          },\n          \"state\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"uploading\",\n              \"online\"\n            ],\n            \"description\": \"uploading until the item is finished, then online.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"MediaList\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"items\",\n          \"next\"\n        ],\n        \"properties\": {\n          \"items\": {\n            \"type\": \"array\",\n            \"maxItems\": 50,\n            \"items\": {\n              \"$ref\": \"#/components/schemas/MediaItem\"\n            },\n            \"description\": \"Newest first.\"\n          },\n          \"next\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Send it as cursor for the next page. null on the last page.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"MediaTooLarge\": {\n        \"type\": \"object\",\n        \"description\": \"The item is larger than this server takes. Nothing was stored.\",\n        \"required\": [\n          \"error\",\n          \"detail\",\n          \"max_bytes\",\n          \"max_side\"\n        ],\n        \"properties\": {\n          \"error\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"media_too_large\"\n            ]\n          },\n          \"detail\": {\n            \"type\": \"string\",\n            \"description\": \"The same in words. The text may change; do not match on it.\"\n          },\n          \"max_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"The most bytes an item of this kind may have here.\"\n          },\n          \"max_side\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"The most pixels an item of this kind may have on a side.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"SignInRequest\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"email\"\n        ],\n        \"properties\": {\n          \"email\": {\n            \"type\": \"string\",\n            \"minLength\": 3,\n            \"maxLength\": 254,\n            \"description\": \"The address to send the link to. Spaces around it are dropped and capitals do not count.\"\n          }\n        }\n      },\n      \"SignInComplete\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"code\"\n        ],\n        \"properties\": {\n          \"code\": {\n            \"type\": \"string\",\n            \"pattern\": \"^dpl_[0-9a-f]{40}$\",\n            \"description\": \"The code of the link, the part after #c= in its address.\"\n          }\n        }\n      },\n      \"EmailChangeRequest\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"email\"\n        ],\n        \"properties\": {\n          \"email\": {\n            \"type\": \"string\",\n            \"minLength\": 3,\n            \"maxLength\": 254,\n            \"description\": \"The new address, which the link is mailed to. Spaces around it are dropped and capitals do not count.\"\n          }\n        }\n      },\n      \"EmailChangeConfirm\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"code\"\n        ],\n        \"properties\": {\n          \"code\": {\n            \"type\": \"string\",\n            \"pattern\": \"^dpe_[0-9a-f]{40}$\",\n            \"description\": \"The code of the link mailed to the new address, the part after #c= in its address.\"\n          }\n        }\n      },\n      \"EmailChanged\": {\n        \"type\": \"object\",\n        \"description\": \"The change was made.\",\n        \"required\": [\n          \"email\",\n          \"previous_email\"\n        ],\n        \"properties\": {\n          \"email\": {\n            \"type\": \"string\",\n            \"description\": \"The account's address from now on.\"\n          },\n          \"previous_email\": {\n            \"type\": \"string\",\n            \"description\": \"The address it had, which was sent a notice.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Ok\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"ok\"\n        ],\n        \"properties\": {\n          \"ok\": {\n            \"type\": \"boolean\",\n            \"const\": true\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Session\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"account\",\n          \"workspace\",\n          \"session\",\n          \"csrf\",\n          \"email_change\"\n        ],\n        \"properties\": {\n          \"account\": {\n            \"type\": \"object\",\n            \"description\": \"The account the session belongs to.\",\n            \"required\": [\n              \"id\",\n              \"username\",\n              \"email\",\n              \"admin\"\n            ],\n            \"properties\": {\n              \"id\": {\n                \"type\": \"string\",\n                \"pattern\": \"^usr_[0-9a-f]{24}$\"\n              },\n              \"username\": {\n                \"type\": [\n                  \"string\",\n                  \"null\"\n                ],\n                \"description\": \"null until the account has one.\"\n              },\n              \"email\": {\n                \"type\": \"string\"\n              },\n              \"admin\": {\n                \"type\": \"boolean\",\n                \"description\": \"true for the site's admin.\"\n              }\n            },\n            \"additionalProperties\": false\n          },\n          \"workspace\": {\n            \"type\": \"object\",\n            \"description\": \"The account's workspace, the one every request of the session acts in.\",\n            \"required\": [\n              \"id\",\n              \"name\"\n            ],\n            \"properties\": {\n              \"id\": {\n                \"type\": \"string\",\n                \"pattern\": \"^ws_[0-9a-f]{24}$\"\n              },\n              \"name\": {\n                \"type\": \"string\"\n              }\n            },\n            \"additionalProperties\": false\n          },\n          \"session\": {\n            \"type\": \"object\",\n            \"description\": \"This session.\",\n            \"required\": [\n              \"id\",\n              \"created_at\",\n              \"expires_at\"\n            ],\n            \"properties\": {\n              \"id\": {\n                \"type\": \"string\",\n                \"pattern\": \"^ses_[0-9a-f]{24}$\"\n              },\n              \"created_at\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"When the browser signed in, in milliseconds since 1970.\"\n              },\n              \"expires_at\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"When the session ends unless it is used, in milliseconds since 1970.\"\n              }\n            },\n            \"additionalProperties\": false\n          },\n          \"csrf\": {\n            \"type\": \"string\",\n            \"pattern\": \"^[0-9a-f]{64}$\",\n            \"description\": \"The anti-forgery value: send it in the X-Csrf-Token header of every change made with this session.\"\n          },\n          \"email_change\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when the site can mail the link an email change needs; false when its mail is off, and POST /api/v1/account/email then answers mail_off.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"SessionList\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"sessions\"\n        ],\n        \"properties\": {\n          \"sessions\": {\n            \"type\": \"array\",\n            \"description\": \"The account's live sessions, the current one first.\",\n            \"items\": {\n              \"type\": \"object\",\n              \"required\": [\n                \"id\",\n                \"label\",\n                \"created_at\",\n                \"last_used_at\",\n                \"expires_at\",\n                \"current\"\n              ],\n              \"properties\": {\n                \"id\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^ses_[0-9a-f]{24}$\"\n                },\n                \"label\": {\n                  \"type\": \"string\",\n                  \"maxLength\": 40,\n                  \"description\": \"The browser and the system it was signed in on, such as Firefox on Linux, or Unknown browser.\"\n                },\n                \"created_at\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 0,\n                  \"description\": \"When it was signed in, in milliseconds since 1970.\"\n                },\n                \"last_used_at\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 0,\n                  \"description\": \"When it was last used, to the hour, in milliseconds since 1970.\"\n                },\n                \"expires_at\": {\n                  \"type\": \"integer\",\n                  \"minimum\": 0,\n                  \"description\": \"When it ends unless it is used, in milliseconds since 1970.\"\n                },\n                \"current\": {\n                  \"type\": \"boolean\",\n                  \"description\": \"true for the session this request was sent with.\"\n                }\n              },\n              \"additionalProperties\": false\n            }\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"AdminAccount\": {\n        \"type\": \"object\",\n        \"description\": \"One account and how its workspace uses its storage. Nothing of the workspace's tours: no tour, title, link, picture, token or session.\",\n        \"required\": [\n          \"id\",\n          \"username\",\n          \"email\",\n          \"status\",\n          \"admin\",\n          \"created_at\",\n          \"workspace_id\",\n          \"workspace_name\",\n          \"tours\",\n          \"used_bytes\",\n          \"allowance_bytes\",\n          \"storage_allowance_bytes\",\n          \"over\",\n          \"counted\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^usr_[0-9a-f]{24}$\",\n            \"description\": \"The account's id.\"\n          },\n          \"username\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"null until the account has one.\"\n          },\n          \"email\": {\n            \"type\": \"string\",\n            \"description\": \"The address the account signs in with.\"\n          },\n          \"status\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"active\",\n              \"disabled\"\n            ],\n            \"description\": \"disabled: the account cannot sign in, and its workspace's tokens are refused.\"\n          },\n          \"admin\": {\n            \"type\": \"boolean\",\n            \"description\": \"true for the site's admin.\"\n          },\n          \"created_at\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"When the account was made, in milliseconds since 1970.\"\n          },\n          \"workspace_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^ws_[0-9a-f]{24}$\",\n            \"description\": \"The account's workspace: the id to set its allowance with.\"\n          },\n          \"workspace_name\": {\n            \"type\": \"string\",\n            \"description\": \"The workspace's name, as its owner wrote it. Show it as text: it may hold any characters.\"\n          },\n          \"tours\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many tours the workspace has, drafts and published.\"\n          },\n          \"used_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"What the workspace uses, in bytes, counted as GET /api/v1/usage counts it for the account itself.\"\n          },\n          \"allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"The allowance in force, in bytes: the workspace's own number, else the server's setting. null when there is no limit.\"\n          },\n          \"storage_allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"The workspace's own number, in bytes. null when it has none and the site's default applies.\"\n          },\n          \"over\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when more is used than the allowance in force.\"\n          },\n          \"counted\": {\n            \"type\": \"object\",\n            \"description\": \"What used_bytes is made of, in bytes, as in GET /api/v1/usage.\",\n            \"required\": [\n              \"pictures\",\n              \"logos\",\n              \"uploads_in_progress\"\n            ],\n            \"properties\": {\n              \"pictures\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"The images of every step of every tour.\"\n              },\n              \"logos\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"The tours' logos.\"\n              },\n              \"uploads_in_progress\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"description\": \"The room held by uploads that are not finished.\"\n              }\n            },\n            \"additionalProperties\": false\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"AdminSummary\": {\n        \"type\": \"object\",\n        \"description\": \"The site's storage in all. Three numbers, nothing of any workspace.\",\n        \"required\": [\n          \"accounts\",\n          \"used_bytes\",\n          \"standard_allowance_bytes\"\n        ],\n        \"properties\": {\n          \"accounts\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many accounts the site has.\"\n          },\n          \"used_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"What all workspaces use together, in bytes: the sum of every account's used_bytes in the list of accounts.\"\n          },\n          \"standard_allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"The site's standard allowance from the server's settings, in bytes, which every workspace without a number of its own has. null when none is set: no limit.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"AdminAccountList\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"accounts\",\n          \"next\"\n        ],\n        \"properties\": {\n          \"accounts\": {\n            \"type\": \"array\",\n            \"maxItems\": 100,\n            \"description\": \"The accounts, in the order they were made, at most 100.\",\n            \"items\": {\n              \"$ref\": \"#/components/schemas/AdminAccount\"\n            }\n          },\n          \"next\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"pattern\": \"^usr_[0-9a-f]{24}$\",\n            \"description\": \"The id to ask for the next page with, as ?after=<id>. null on the last page.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"AllowanceChange\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"storage_allowance_bytes\"\n        ],\n        \"properties\": {\n          \"storage_allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"minimum\": 0,\n            \"maximum\": 9007199254740991,\n            \"description\": \"The workspace's allowance in bytes, or null to go back to the site's default.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"AllowanceSet\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"workspace_id\",\n          \"allowance_bytes\",\n          \"storage_allowance_bytes\",\n          \"used_bytes\",\n          \"over\"\n        ],\n        \"properties\": {\n          \"workspace_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^ws_[0-9a-f]{24}$\"\n          },\n          \"allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"The allowance now in force, in bytes. null when there is no limit.\"\n          },\n          \"storage_allowance_bytes\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"description\": \"The workspace's own number as just set. null when the site's default applies.\"\n          },\n          \"used_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"What the workspace uses, in bytes.\"\n          },\n          \"over\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when the workspace uses more than its new allowance. Nothing is deleted: only uploads that need room are refused.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Health\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"ok\"\n        ],\n        \"properties\": {\n          \"ok\": {\n            \"type\": \"boolean\",\n            \"const\": true\n          },\n          \"address\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"tours\",\n              \"app\",\n              \"img\"\n            ],\n            \"description\": \"Only on a server with two addresses (or three, with the optional img address), when asked on one of them: which one this request reached.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"UploadTarget\": {\n        \"description\": \"Where the upload goes.\",\n        \"oneOf\": [\n          {\n            \"$ref\": \"#/components/schemas/TargetNew\"\n          },\n          {\n            \"$ref\": \"#/components/schemas/TargetChapter\"\n          },\n          {\n            \"$ref\": \"#/components/schemas/TargetReplace\"\n          }\n        ]\n      },\n      \"TargetNew\": {\n        \"type\": \"object\",\n        \"description\": \"A new tour, made of this one chapter.\",\n        \"required\": [\n          \"kind\"\n        ],\n        \"properties\": {\n          \"kind\": {\n            \"type\": \"string\",\n            \"const\": \"new\"\n          }\n        }\n      },\n      \"TargetChapter\": {\n        \"type\": \"object\",\n        \"description\": \"A new chapter at the end of an existing tour. The tour keeps its settings and logo.\",\n        \"required\": [\n          \"kind\",\n          \"tour_id\"\n        ],\n        \"properties\": {\n          \"kind\": {\n            \"type\": \"string\",\n            \"const\": \"chapter\"\n          },\n          \"tour_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^tour_[0-9a-f]{24}$\"\n          }\n        }\n      },\n      \"TargetReplace\": {\n        \"type\": \"object\",\n        \"description\": \"Replaces one chapter of an existing tour. The chapter keeps its id, title and position and gets exactly the manifest's steps.\",\n        \"required\": [\n          \"kind\",\n          \"tour_id\",\n          \"chapter_id\"\n        ],\n        \"properties\": {\n          \"kind\": {\n            \"type\": \"string\",\n            \"const\": \"replace\"\n          },\n          \"tour_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^tour_[0-9a-f]{24}$\"\n          },\n          \"chapter_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^ch_[0-9a-f]{24}$\"\n          }\n        }\n      },\n      \"UploadCreate\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"manifest\",\n          \"target\"\n        ],\n        \"properties\": {\n          \"manifest\": {\n            \"$ref\": \"#/components/schemas/Manifest\"\n          },\n          \"target\": {\n            \"$ref\": \"#/components/schemas/UploadTarget\"\n          },\n          \"sha256\": {\n            \"type\": \"array\",\n            \"maxItems\": 200,\n            \"items\": {\n              \"type\": \"string\",\n              \"pattern\": \"^[0-9a-f]{64}$\"\n            },\n            \"description\": \"Only with the target replace, and optional: one SHA-256 per step of the manifest, in order, of the image the client would send. The answer's have then lists the steps not to send.\"\n          },\n          \"logo_bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"maximum\": 200000,\n            \"description\": \"Optional: the length in bytes of the logo this upload will send. It counts only for an upload that takes a logo (a new tour, or the replacement of a tour's first chapter) and whose manifest names one; any other upload ignores it. The logo sent must then have exactly this length, and on a workspace with a storage allowance the upload needs this much room for the logo. Without it a logo of any allowed length is taken, and the upload needs 200,000 bytes of room for it.\"\n          }\n        }\n      },\n      \"UploadCreated\": {\n        \"type\": \"object\",\n        \"description\": \"The answer for the targets new and chapter.\",\n        \"required\": [\n          \"upload_id\",\n          \"steps\"\n        ],\n        \"properties\": {\n          \"upload_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^up_[0-9a-f]{24}$\"\n          },\n          \"steps\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"How many step images the upload expects.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"ReplaceCreated\": {\n        \"type\": \"object\",\n        \"description\": \"The answer for the target replace.\",\n        \"required\": [\n          \"upload_id\",\n          \"steps\",\n          \"have\",\n          \"settings\"\n        ],\n        \"properties\": {\n          \"upload_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^up_[0-9a-f]{24}$\"\n          },\n          \"steps\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"description\": \"How many steps the manifest has.\"\n          },\n          \"have\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"integer\",\n              \"minimum\": 1\n            },\n            \"description\": \"The step numbers whose image the chapter already has; do not send them. Empty without sha256.\"\n          },\n          \"settings\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when the chapter is the tour's first: the commit then also replaces the tour's settings and logo with the manifest's.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Committed\": {\n        \"type\": \"object\",\n        \"description\": \"The answer for the targets new and chapter.\",\n        \"required\": [\n          \"tour_id\",\n          \"chapter_id\",\n          \"steps\"\n        ],\n        \"properties\": {\n          \"tour_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^tour_[0-9a-f]{24}$\"\n          },\n          \"chapter_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^ch_[0-9a-f]{24}$\"\n          },\n          \"steps\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many steps the chapter has.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"ReplaceCommitted\": {\n        \"type\": \"object\",\n        \"description\": \"The answer for the target replace.\",\n        \"required\": [\n          \"tour_id\",\n          \"chapter_id\",\n          \"steps\",\n          \"publish\"\n        ],\n        \"properties\": {\n          \"tour_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^tour_[0-9a-f]{24}$\"\n          },\n          \"chapter_id\": {\n            \"type\": \"string\",\n            \"pattern\": \"^ch_[0-9a-f]{24}$\"\n          },\n          \"steps\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"How many steps the chapter has now.\"\n          },\n          \"publish\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"draft\",\n              \"ready\",\n              \"other_changes\"\n            ],\n            \"description\": \"What publishing the tour would do now. draft: the tour is not published; nothing is public and nothing needs publishing. ready: the tour is published and the only changes not public yet are replaces of this chapter; publish it to put the update live. other_changes: the tour is published and its draft holds more than replaces of this chapter that was never published; publishing would put all of it live.\"\n          }\n        },\n        \"additionalProperties\": false\n      },\n      \"Manifest\": {\n        \"type\": \"object\",\n        \"description\": \"The tour as the recorder wrote it, at most 262,144 bytes. The server checks every field: unknown fields are dropped, and anything out of range, of the wrong type or over a limit is refused with 400 bad_manifest and the field's path, never cut short. Text is trimmed and may hold no control or format characters. theme, zoom, cover, cta, end and autoplay are read from version 3 only. The full rules are in src/manifest.ts.\",\n        \"required\": [\n          \"version\",\n          \"generator\",\n          \"title\",\n          \"steps\"\n        ],\n        \"properties\": {\n          \"version\": {\n            \"type\": \"integer\",\n            \"enum\": [\n              1,\n              2,\n              3\n            ],\n            \"description\": \"Version 1 has steps only; version 2 adds spotlights and notes; version 3 adds cards, the cover, the button, the end card and the tour's look.\"\n          },\n          \"generator\": {\n            \"type\": \"string\",\n            \"maxLength\": 100,\n            \"description\": \"The program that wrote the manifest.\"\n          },\n          \"title\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 200,\n            \"description\": \"The tour's title; for a new chapter, the chapter's.\"\n          },\n          \"steps\": {\n            \"type\": \"array\",\n            \"minItems\": 1,\n            \"maxItems\": 200,\n            \"items\": {\n              \"$ref\": \"#/components/schemas/ManifestStep\"\n            },\n            \"description\": \"The steps in order. No two may name the same image.\"\n          },\n          \"spotlight_dim\": {\n            \"type\": [\n              \"integer\",\n              \"null\"\n            ],\n            \"minimum\": 10,\n            \"maximum\": 90,\n            \"description\": \"From version 2: how dark the rest of the picture gets around a spotlight, in percent. Required when a step has a spotlight.\"\n          },\n          \"theme\": {\n            \"$ref\": \"#/components/schemas/Theme\"\n          },\n          \"zoom\": {\n            \"$ref\": \"#/components/schemas/Zoom\"\n          },\n          \"cover\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Cover\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"cta\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Link\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"end\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/EndCard\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"autoplay\": {\n            \"$ref\": \"#/components/schemas/Autoplay\"\n          }\n        }\n      },\n      \"ManifestStep\": {\n        \"type\": \"object\",\n        \"description\": \"One step: a picture, where it was clicked, and what is drawn over it. click is required; null means no click.\",\n        \"required\": [\n          \"image\",\n          \"width\",\n          \"height\",\n          \"bytes\",\n          \"click\",\n          \"t_ms\"\n        ],\n        \"properties\": {\n          \"image\": {\n            \"type\": \"string\",\n            \"pattern\": \"^step-[0-9]{3}\\\\.(png|jpg)$\",\n            \"description\": \"The image's name; its ending says whether a PNG or a JPEG will be sent.\"\n          },\n          \"width\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"maximum\": 4096,\n            \"description\": \"The image's width in pixels; the image sent must have it.\"\n          },\n          \"height\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"maximum\": 4096,\n            \"description\": \"The image's height in pixels; the image sent must have it.\"\n          },\n          \"bytes\": {\n            \"type\": \"integer\",\n            \"minimum\": 1,\n            \"maximum\": 2000000,\n            \"description\": \"The image's length in bytes; the image sent must have it.\"\n          },\n          \"click\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Point\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"t_ms\": {\n            \"type\": \"integer\",\n            \"minimum\": 0,\n            \"description\": \"When the step was recorded, in milliseconds from the start.\"\n          },\n          \"spotlight\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Box\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"notes\": {\n            \"type\": \"array\",\n            \"maxItems\": 20,\n            \"items\": {\n              \"$ref\": \"#/components/schemas/Note\"\n            },\n            \"description\": \"From version 2.\"\n          },\n          \"card\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Card\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"advance\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"hotspot\",\n              \"anywhere\"\n            ],\n            \"description\": \"From version 3: whether a click on the hotspot or anywhere moves on. hotspot when absent.\"\n          },\n          \"zoom\": {\n            \"type\": [\n              \"boolean\",\n              \"null\"\n            ],\n            \"description\": \"From version 3: this step's own zoom; null follows the tour's.\"\n          }\n        }\n      },\n      \"Point\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"x\",\n          \"y\"\n        ],\n        \"properties\": {\n          \"x\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the image's width.\"\n          },\n          \"y\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the image's height.\"\n          }\n        }\n      },\n      \"Box\": {\n        \"type\": \"object\",\n        \"description\": \"A box in percent of the image; it must end inside the image.\",\n        \"required\": [\n          \"x\",\n          \"y\",\n          \"w\",\n          \"h\"\n        ],\n        \"properties\": {\n          \"x\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the width.\"\n          },\n          \"y\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the height.\"\n          },\n          \"w\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Above 0.\"\n          },\n          \"h\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Above 0.\"\n          }\n        }\n      },\n      \"Note\": {\n        \"description\": \"A note drawn on the picture.\",\n        \"oneOf\": [\n          {\n            \"$ref\": \"#/components/schemas/TextNote\"\n          },\n          {\n            \"$ref\": \"#/components/schemas/BubbleNote\"\n          }\n        ]\n      },\n      \"TextNote\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"kind\",\n          \"x\",\n          \"y\",\n          \"text\",\n          \"size\",\n          \"color\"\n        ],\n        \"properties\": {\n          \"kind\": {\n            \"type\": \"string\",\n            \"const\": \"text\"\n          },\n          \"x\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the width.\"\n          },\n          \"y\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the height.\"\n          },\n          \"text\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 500,\n            \"description\": \"May hold line feeds.\"\n          },\n          \"size\": {\n            \"type\": \"number\",\n            \"exclusiveMinimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"The text size, in percent of the image's height.\"\n          },\n          \"color\": {\n            \"type\": \"string\",\n            \"pattern\": \"^#[0-9A-Fa-f]{6}$\",\n            \"description\": \"The text colour, #rrggbb.\"\n          }\n        }\n      },\n      \"BubbleNote\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"kind\",\n          \"x\",\n          \"y\",\n          \"w\",\n          \"h\",\n          \"tail\",\n          \"text\",\n          \"size\",\n          \"color\",\n          \"fill\"\n        ],\n        \"properties\": {\n          \"kind\": {\n            \"type\": \"string\",\n            \"const\": \"bubble\"\n          },\n          \"x\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the width.\"\n          },\n          \"y\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Percent of the height.\"\n          },\n          \"w\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Above 0.\"\n          },\n          \"h\": {\n            \"type\": \"number\",\n            \"minimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"Above 0.\"\n          },\n          \"tail\": {\n            \"$ref\": \"#/components/schemas/Point\"\n          },\n          \"text\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 500,\n            \"description\": \"May hold line feeds.\"\n          },\n          \"size\": {\n            \"type\": \"number\",\n            \"exclusiveMinimum\": 0,\n            \"maximum\": 100,\n            \"description\": \"The text size, in percent of the image's height.\"\n          },\n          \"color\": {\n            \"type\": \"string\",\n            \"pattern\": \"^#[0-9A-Fa-f]{6}$\",\n            \"description\": \"The text colour, #rrggbb.\"\n          },\n          \"fill\": {\n            \"type\": \"string\",\n            \"pattern\": \"^#[0-9A-Fa-f]{6}$\",\n            \"description\": \"The bubble's colour, #rrggbb.\"\n          }\n        }\n      },\n      \"Card\": {\n        \"type\": \"object\",\n        \"description\": \"From version 3: the step's card. It needs a title or a body.\",\n        \"required\": [],\n        \"properties\": {\n          \"title\": {\n            \"type\": \"string\",\n            \"maxLength\": 80,\n            \"description\": \"Empty when absent.\"\n          },\n          \"body\": {\n            \"type\": \"string\",\n            \"maxLength\": 300,\n            \"description\": \"May hold line feeds. Empty when absent.\"\n          },\n          \"next_label\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 24,\n            \"description\": \"Next when absent.\"\n          },\n          \"anchor\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"hotspot\",\n              \"point\",\n              \"none\"\n            ],\n            \"description\": \"Where the card points. hotspot (the default) needs a step with a click; point needs point.\"\n          },\n          \"point\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Point\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"placement\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"auto\",\n              \"top\",\n              \"bottom\",\n              \"left\",\n              \"right\"\n            ],\n            \"description\": \"auto when absent.\"\n          }\n        }\n      },\n      \"Link\": {\n        \"type\": \"object\",\n        \"description\": \"A button with a link.\",\n        \"required\": [\n          \"label\",\n          \"url\"\n        ],\n        \"properties\": {\n          \"label\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 24,\n            \"description\": \"The button's text.\"\n          },\n          \"url\": {\n            \"type\": \"string\",\n            \"maxLength\": 500,\n            \"description\": \"An https link with a plain host name: no user name, no IP address, no spaces.\"\n          }\n        }\n      },\n      \"Theme\": {\n        \"type\": \"object\",\n        \"description\": \"From version 3: the tour's look. Every field has a default.\",\n        \"required\": [],\n        \"properties\": {\n          \"card_style\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"dark\",\n              \"light\",\n              \"compact\",\n              \"auto\"\n            ]\n          },\n          \"accent\": {\n            \"type\": \"string\",\n            \"pattern\": \"^#[0-9A-Fa-f]{6}$\",\n            \"description\": \"#rrggbb.\"\n          },\n          \"hotspot\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"pulse\",\n              \"dot\",\n              \"none\"\n            ]\n          },\n          \"progress_bar\": {\n            \"type\": \"boolean\"\n          },\n          \"backdrop\": {\n            \"type\": \"string\",\n            \"pattern\": \"^(auto|#[0-9A-Fa-f]{6})$\",\n            \"description\": \"auto, or a colour as #rrggbb.\"\n          },\n          \"spotlight_soft\": {\n            \"type\": \"boolean\"\n          }\n        }\n      },\n      \"Zoom\": {\n        \"type\": \"object\",\n        \"description\": \"From version 3: whether steps zoom in on the click, and how far.\",\n        \"required\": [],\n        \"properties\": {\n          \"enabled\": {\n            \"type\": \"boolean\"\n          },\n          \"percent\": {\n            \"type\": \"integer\",\n            \"minimum\": 105,\n            \"maximum\": 140\n          }\n        }\n      },\n      \"Cover\": {\n        \"type\": \"object\",\n        \"description\": \"From version 3: the page shown before the first step.\",\n        \"required\": [\n          \"title\"\n        ],\n        \"properties\": {\n          \"title\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 80,\n            \"description\": \"The cover's title.\"\n          },\n          \"body\": {\n            \"type\": \"string\",\n            \"maxLength\": 200,\n            \"description\": \"May hold line feeds. Empty when absent.\"\n          },\n          \"button\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 24,\n            \"description\": \"Start when absent.\"\n          },\n          \"logo\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"enum\": [\n              \"logo.png\",\n              \"logo.jpg\",\n              null\n            ],\n            \"description\": \"Names the logo this upload will send, by its type; null for none.\"\n          }\n        }\n      },\n      \"EndCard\": {\n        \"type\": \"object\",\n        \"description\": \"From version 3: the card shown after the last step.\",\n        \"required\": [],\n        \"properties\": {\n          \"text\": {\n            \"type\": \"string\",\n            \"maxLength\": 200,\n            \"description\": \"May hold line feeds. Empty when absent.\"\n          },\n          \"primary\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Link\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"secondary\": {\n            \"oneOf\": [\n              {\n                \"$ref\": \"#/components/schemas/Link\"\n              },\n              {\n                \"type\": \"null\"\n              }\n            ]\n          },\n          \"replay\": {\n            \"type\": \"boolean\",\n            \"description\": \"true when absent.\"\n          }\n        }\n      },\n      \"Autoplay\": {\n        \"type\": \"object\",\n        \"description\": \"From version 3: whether the tour moves on by itself, and after how long.\",\n        \"required\": [],\n        \"properties\": {\n          \"enabled\": {\n            \"type\": \"boolean\"\n          },\n          \"seconds\": {\n            \"type\": \"integer\",\n            \"minimum\": 2,\n            \"maximum\": 20\n          }\n        }\n      }\n    },\n    \"responses\": {\n      \"Unauthorized\": {\n        \"description\": \"The token or session is missing, malformed, unknown, expired or revoked.\",\n        \"content\": {\n          \"application/json\": {\n            \"schema\": {\n              \"$ref\": \"#/components/schemas/Unauthorized\"\n            }\n          }\n        }\n      }\n    }\n  }\n}\n";
export const OPENAPI_JSON_ETAG = "\"97999542a21956a2fcfdb9f1a0d0ec9f\"";
export const OPENAPI_YAML: string = "openapi: 3.1.0\ninfo:\n  title: Mythicshot API\n  version: 0.1.19\n  description: |-\n    Upload, publish and manage interactive product tours. This is the API Mythicshot itself uses.\n\n    ## Get connected\n\n    Every request except the health check and the two sign-in requests carries a token, as the header `Authorization: Bearer YOUR_TOKEN`, or a session cookie (see below). A token starts with \"dp_\" and is 43 characters long. It acts only inside its own workspace: another workspace's tour answers 404, the same as one that does not exist.\n\n    The first request to try answers with your workspace's name and the server's version:\n\n    ```\n    curl https://YOUR-SITE/api/v1/me -H \"Authorization: Bearer YOUR_TOKEN\"\n    ```\n\n    ## Signing in and sessions\n\n    The site's own pages sign a person in with a link sent by mail: POST /api/v1/signin/request mails the link, and POST /api/v1/signin/complete turns the code in it into a session. The link works once and for 15 minutes. The session is a cookie, __Host-dp_session, on the app address only (on a server with one address, on that address); it lasts 30 days from its last use. Every request that lists the session can be sent with it instead of a token, and acts in the account's one workspace.\n\n    A signed-in person changes the account's email address in two steps: POST /api/v1/account/email mails a link to the new address, and POST /api/v1/account/email/confirm, sent with the code in that link from the same account's session, makes the change, once and within 15 minutes. The old address is then sent a notice. Both need the session; a token cannot change an address.\n\n    A request with a session that changes anything (any method but GET and HEAD) must come from the site's own pages: its Origin must be the address it is sent to, and it must carry the session's anti-forgery value in the header `X-Csrf-Token`, which GET /api/v1/session gives. A token and a session cookie together are refused.\n\n    The documentation page never sends a cookie, so a session cannot be tried from it; with a token, try the requests that take one.\n\n    ## Errors\n\n    Every refusal is JSON with an error code and, mostly, a detail in plain words: `{\"error\":\"bad_title\",\"detail\":\"the title must not be empty\"}`. The codes are stable; the detail text may change.\n\n    Some answers can come from any request and are not repeated on each one:\n\n    - `401 {\"error\":\"unauthorized\"}`, with no detail: the token or session cookie is missing, malformed, unknown, expired or revoked, or a session cookie was sent to the tours address.\n    - `400 {\"error\":\"mixed_credentials\",\"detail\":\"send a token or a session cookie, not both\"}`: the request carries a token and a session cookie.\n    - `403 {\"error\":\"bad_origin\",\"detail\":\"this request must come from the site's own pages\"}`: a change made with a session did not come from a page of the address it was sent to.\n    - `403 {\"error\":\"bad_csrf\",\"detail\":\"the anti-forgery header is missing or wrong\"}`: a change made with a session lacks the session's X-Csrf-Token.\n    - `404 {\"error\":\"not_found\"}`, with no detail: no request has that address.\n    - `421` with nothing in it: on a server with two addresses, the request was sent to another host name.\n    - `500 {\"error\":\"internal\"}`: the server failed; nothing about the failure is given.\n    - `500 {\"error\":\"misconfigured\"}`: on Cloudflare, the two addresses in the settings cannot be used together; every request answers this until they are fixed.\n\n    The admin routes (under /api/v1/admin/) answer every refusal, the 400 and the two 403s above included, with the one `404 {\"error\":\"not_found\"}`.\n\n    ## Requests that work in steps\n\n    Publish, unpublish and delete may need several requests for a large tour. Each is safe to send again: send the same request until it answers 200 or 204.\n\n    ## Limits\n\n    - 200 steps in one upload, and 20 notes on a step.\n    - The manifest: 262,144 bytes.\n    - A step image: 2,000,000 bytes and 4,096 pixels on a side, PNG or JPEG.\n    - The logo: 200,000 bytes and 512 pixels on a side, PNG or JPEG.\n    - Text, in characters after trimming: title 200, generator 100, note text 500, card title 80, card body 300, next label 24, cover title 80, cover body 200, cover button 24, button label 24, end text 200, link 500.\n    - 400 steps in one published tour, and 512,000 bytes for its text (titles, notes, cards and settings together).\n    - One publish request copies up to 12 images; one delete request removes up to 250 files.\n    - 5 open uploads per workspace, unless the server's settings give another number.\n    - An upload that is not finished is removed after 24 hours.\n    - A shared image: 10,485,760 bytes and 8,192 pixels on a side, PNG or JPEG. A shared clip: 52,428,800 bytes, GIF or MP4, at most 8,192 pixels on a side and 10 minutes long. The server's settings can give other numbers for the image and clip sizes. Each is sent in parts of 2,000,000 bytes. An item's preview: 100,000 bytes and 512 pixels on a side, PNG or JPEG. A workspace starts at most 60 items an hour, and an item that is not finished is removed after 24 hours.\n    - A workspace may have a storage allowance, set by the server's settings or its admin. An upload or a shared item that would take the workspace over it is refused when it is started, with 413 `storage_full` and the numbers, before anything is stored. Nothing is ever deleted because of an allowance.\n    - A publish that makes no progress for 15 minutes counts as abandoned.\n\n    Anything over a limit is refused, never cut short.\nservers:\n  - url: /\ntags:\n  - name: Tours\n    description: List, rename, publish, unpublish and delete tours, and read a draft step's image.\n  - name: Uploads\n    description: \"Send a tour, a new chapter or a chapter's replacement: start, one request per image, finish.\"\n  - name: Items\n    description: \"Share a single image or a short clip: start, one request per part, an optional preview, finish; then list, read and delete.\"\n  - name: Workspace\n    description: The workspace a token or a session belongs to.\n  - name: Accounts\n    description: Signing in with a link sent by mail, the browser sessions of an account, and changing its email address. The site's own pages use these.\n  - name: Admin\n    description: \"For the site's admin alone: the site's storage in all, how each account uses its storage, and each workspace's allowance. To anyone else these answer 404.\"\n  - name: Server\n    description: Whether the server is up. Needs no token.\npaths:\n  /api/v1/tours:\n    get:\n      tags:\n        - Tours\n      summary: List the workspace's tours\n      description: Every tour of the token's workspace, drafts and published, most recently changed first. url is the public link as a path, /t/<slug>, to put after the server address; it and published_at are null for a draft.\n      operationId: listTours\n      security: &a1\n        - token: []\n        - session: []\n      responses:\n        \"200\":\n          description: The tours.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/TourList\"\n        \"401\": &a2\n          $ref: \"#/components/responses/Unauthorized\"\n  /api/v1/tours/{id}:\n    patch:\n      tags:\n        - Tours\n      summary: Rename a tour\n      description: \"Changes the title only. The title follows the rule of a tour's title at upload: trimmed, 1 to 200 characters, no control or format characters. The slug and the public link stay the same. A rename shows on the public page of a published tour at once, without publishing again.\"\n      operationId: renameTour\n      security: *a1\n      parameters:\n        - &a3\n          name: id\n          in: path\n          required: true\n          description: The tour's id, as the tour list and an upload's commit give it.\n          schema:\n            type: string\n            pattern: ^tour_[0-9a-f]{24}$\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/RenameBody\"\n      responses:\n        \"200\":\n          description: The tour's id, and the title as saved.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Renamed\"\n        \"400\":\n          description: \"bad_request: the body is not a JSON object. bad_title: the title breaks the rule; the detail says how.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_title\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\": &a4\n          description: \"No such tour in this workspace: unknown, another workspace's, or already deleted.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: The request body is too long.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_large\n                  detail:\n                    type: string\n                additionalProperties: false\n    delete:\n      tags:\n        - Tours\n      summary: Delete a tour, in steps\n      description: 'Removes the tour, its chapters and steps, its draft images and logo, its published images and any unfinished upload into it. This cannot be undone. A large tour takes several requests, each removing up to 250 files: send the same request until it answers 200. From the first request on, the tour is gone from the list and its public page answers 404; the later requests only remove files. A repeated request after the tour is gone answers 404, so treat 404 as \"gone\". Delete does not stop a publish in progress: let it finish, or unpublish the tour, then delete.'\n      operationId: deleteTour\n      security: *a1\n      parameters:\n        - *a3\n      responses:\n        \"200\":\n          description: Nothing of the tour is left.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Deleted\"\n        \"202\":\n          description: The tour is deleted; files remain to remove. Send the same request again.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/InProgress\"\n        \"401\": *a2\n        \"404\": *a4\n        \"409\":\n          description: A publish of this tour is in progress. Wait for it to finish, or unpublish the tour to stop it, then delete again.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - publish_busy\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"500\":\n          description: The tour is deleted, but some of its files could not be removed yet. Send the same request again.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - cleanup_pending\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/tours/{id}/publish:\n    post:\n      tags:\n        - Tours\n      summary: Publish a tour, in steps\n      description: \"Copies the tour's draft into a public version at its link. Send it with no body to start, or to join the publish already in progress for the current draft. A small tour answers 200 at once. A large one answers 202 with a publish_id: send the request again with that id, each request copying up to 12 images, until it answers 200. Visitors see the previously published version until the last request, and a publish that did not finish never touches it. A publish works from the draft as it was when it started. A tour of more than 400 steps, or one whose text is over 512,000 bytes, answers 413 on the first request, before anything is copied. A publish with no progress for 15 minutes counts as abandoned, and the next request without a publish_id starts a new one.\"\n      operationId: publishTour\n      security: *a1\n      parameters:\n        - *a3\n      requestBody:\n        required: false\n        description: Empty to start; the previous answer's publish_id to continue.\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/PublishBody\"\n      responses:\n        \"200\":\n          description: The new version is live. The same answer on any repeat.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Published\"\n        \"202\":\n          description: Images are being copied. Send the request again with this publish_id.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/PublishInProgress\"\n        \"400\":\n          description: \"bad_request: the body is neither empty nor a publish_id. empty_tour: a tour with no steps cannot be published.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - empty_tour\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\": *a4\n        \"409\":\n          description: \"publish_cancelled: that publish was stopped before it finished (the tour was unpublished, the publish failed or was abandoned, or a fresh start replaced it); publish again to start over. publish_busy: another publish of the tour is starting at this moment, or its draft changed while this one was starting; nothing was written, try again.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - publish_cancelled\n                      - publish_busy\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: The tour has too many steps or too much text to publish, or the request body is too long.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_large\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"500\":\n          description: The tour could not be published. What was published before is unchanged.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - publish_failed\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/tours/{id}/unpublish:\n    post:\n      tags:\n        - Tours\n      summary: Unpublish a tour\n      description: \"Takes the tour's public page and images down at once and makes the tour a draft again. A publish in progress is cancelled. Removing a large tour's public images can take more than one request: send the same request until it answers 204. Unpublishing a draft answers 204 too.\"\n      operationId: unpublishTour\n      security: *a1\n      parameters:\n        - *a3\n      responses:\n        \"202\":\n          description: The tour is unpublished; public images remain to remove. Send the same request again.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/UnpublishInProgress\"\n        \"204\":\n          description: The tour is a draft and all its public images are gone.\n        \"401\": *a2\n        \"404\": *a4\n        \"500\":\n          description: The tour is unpublished, but some of its public images could not be removed yet. Send the same request again.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - cleanup_pending\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/tours/{id}/steps/{step_id}/image:\n    get:\n      tags:\n        - Tours\n      summary: Get a draft step's image\n      description: The picture of one step of the draft, as it was uploaded. The type is the one the server read from the file's own bytes at upload. Nothing may cache it but the client that asked.\n      operationId: getStepImage\n      security: *a1\n      parameters:\n        - *a3\n        - name: step_id\n          in: path\n          required: true\n          description: The step's id.\n          schema:\n            type: string\n            pattern: ^st_[0-9a-f]{24}$\n      responses:\n        \"200\":\n          description: The image.\n          headers:\n            content-security-policy:\n              description: Always `default-src 'none'; sandbox`, so the picture can do nothing when opened on its own.\n              schema:\n                type: string\n                const: default-src 'none'; sandbox\n            cache-control:\n              description: Always `private, no-store`.\n              schema:\n                type: string\n                const: private, no-store\n          content: &a5\n            image/png:\n              schema:\n                type: string\n                format: binary\n            image/jpeg:\n              schema:\n                type: string\n                format: binary\n        \"401\": *a2\n        \"404\":\n          description: No such step in this workspace.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/uploads:\n    post:\n      tags:\n        - Uploads\n      summary: Start an upload\n      description: \"Starts an upload from the tour's manifest (at most 262,144 bytes) and says where it goes: a new tour, a new chapter of a tour, or the replacement of a chapter. Then send each step's image, the logo if one is due, and finish the upload; nothing changes in any tour until then. A replace changes the draft only: the public page stays as it was until the tour is published again. A workspace may have 5 open uploads at a time (the server's settings can give another number), and an upload that is not finished is removed after 24 hours. A repeated request only makes another upload. On a workspace with a storage allowance, an upload that would take it over is refused here with 413 storage_full, before any image is sent. A new tour or a new chapter needs room for all its images; the replacement of a chapter needs room only for what its images come to above the chapter's present ones. An upload that carries a logo (a new tour, or the replacement of a tour's first chapter, when the manifest names a logo) also needs room for the logo: logo_bytes when the request gives it, and without logo_bytes up to 200,000 bytes; for a replacement, only what that comes to above the size recorded for the tour's present logo. So a replacement that does not grow the chapter is never refused for storage when it carries no logo, or gives a logo_bytes no larger than the present logo's recorded size.\"\n      operationId: createUpload\n      security: *a1\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/UploadCreate\"\n      responses:\n        \"201\":\n          description: The upload exists. For the target replace the answer also has have and settings.\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - $ref: \"#/components/schemas/UploadCreated\"\n                  - $ref: \"#/components/schemas/ReplaceCreated\"\n        \"400\":\n          description: \"bad_request: the body is not a JSON object, or sha256 is not one 64-character lowercase hex text per step, or comes with another target than replace, or logo_bytes is not a whole number from 1 to 200,000. bad_manifest: the manifest breaks a rule; the detail names the field. bad_target: the target is missing or its kind is not new, chapter or replace.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_manifest\n                      - bad_target\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\":\n          description: \"The target's tour is not in this workspace (detail: no such tour), or the chapter is not a chapter of that tour (detail: no such chapter).\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: \"too_large: the request body is too long. storage_full: the upload would take the workspace over its storage allowance; nothing was stored, and the answer carries the numbers in bytes. Deleting tours, or a larger allowance, makes room; waiting does not.\"\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - type: object\n                    required:\n                      - error\n                      - detail\n                    properties:\n                      error:\n                        type: string\n                        enum:\n                          - too_large\n                      detail:\n                        type: string\n                    additionalProperties: false\n                  - $ref: \"#/components/schemas/StorageFull\"\n        \"429\":\n          description: The workspace already has its number of open uploads. Finish or cancel one first.\n          headers:\n            retry-after:\n              description: Seconds to wait before trying again.\n              schema:\n                type: integer\n                minimum: 1\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_many_uploads\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/uploads/{id}/steps/{n}:\n    put:\n      tags:\n        - Uploads\n      summary: Send one step's image\n      description: The body is the image itself, a PNG or a JPEG of at most 2,000,000 bytes and 4,096 pixels on a side. Its type, width, height and length must be exactly what the manifest gives for the step; the server reads them from the file's own bytes, not from the Content-Type. Steps may be sent in any order, each once.\n      operationId: putStepImage\n      security: *a1\n      parameters:\n        - &a6\n          name: id\n          in: path\n          required: true\n          description: The upload's id, from the answer that started it.\n          schema:\n            type: string\n            pattern: ^up_[0-9a-f]{24}$\n        - name: n\n          in: path\n          required: true\n          description: The step's number in the manifest, counted from 1.\n          schema:\n            type: integer\n            minimum: 1\n            maximum: 200\n      requestBody:\n        required: true\n        content: *a5\n      responses:\n        \"204\":\n          description: The image is stored.\n        \"400\":\n          description: The body is not the image the manifest describes; the detail says what differs.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_image\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\":\n          description: \"No such upload in this workspace: unknown, another workspace's, finished or cancelled, or the manifest has no step of that number.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"409\":\n          description: This step was already sent, or the chapter already has its image (a step listed in have).\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - already_sent\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: The image is too long.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_large\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/uploads/{id}/logo:\n    put:\n      tags:\n        - Uploads\n      summary: Send the logo\n      description: The body is the cover's logo, a PNG or a JPEG (as the manifest's cover names it) of at most 200,000 bytes and 512 pixels on a side. Only an upload that makes a new tour, or replaces a tour's first chapter, takes a logo; a tour keeps its logo otherwise. When the upload was started with logo_bytes, the logo must have exactly that length.\n      operationId: putLogo\n      security: *a1\n      parameters:\n        - *a6\n      requestBody:\n        required: true\n        content: *a5\n      responses:\n        \"204\":\n          description: The logo is stored.\n        \"400\":\n          description: The body is not a logo of the type the manifest names, or is too large on a side, or its length differs from the logo_bytes the upload was started with.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_image\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\":\n          description: \"No such upload in this workspace: unknown, another workspace's, finished or cancelled, or its manifest names no logo.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"409\":\n          description: \"logo_not_used: this upload goes into an existing tour, which keeps its logo; do not send one. already_sent: the logo was already sent.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - logo_not_used\n                      - already_sent\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: The logo is too long.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_large\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/uploads/{id}/commit:\n    post:\n      tags:\n        - Uploads\n      summary: Finish an upload\n      description: \"Puts the upload into the draft in one go: a new tour, a new chapter, or the chapter with exactly the manifest's steps. Nothing is public until the tour is published. A repeated request answers 201 with the same ids. For a replace the answer's publish says what publishing would do now: draft, ready or other_changes.\"\n      operationId: commitUpload\n      security: *a1\n      parameters:\n        - *a6\n      responses:\n        \"201\":\n          description: The draft holds the upload. For the target replace the answer also has publish.\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - $ref: \"#/components/schemas/Committed\"\n                  - $ref: \"#/components/schemas/ReplaceCommitted\"\n        \"401\": *a2\n        \"404\":\n          description: \"No such upload in this workspace: unknown, another workspace's, finished or cancelled.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"409\":\n          description: \"incomplete: a step's image, or a logo the upload must carry, has not been sent; nothing changes. chapter_changed: another upload replaced the chapter since this one started; nothing changes: cancel this upload and start again.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - incomplete\n                      - chapter_changed\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/uploads/{id}:\n    delete:\n      tags:\n        - Uploads\n      summary: Cancel an upload\n      description: Removes the upload and only what it stored, never an image a chapter uses. It answers 204 also for an upload that is unknown, finished or already cancelled.\n      operationId: cancelUpload\n      security: *a1\n      parameters:\n        - *a6\n      responses:\n        \"204\":\n          description: The upload is gone, or was not there.\n        \"401\": *a2\n  /api/v1/media:\n    post:\n      tags:\n        - Items\n      summary: Start a shared item\n      description: \"Starts sharing one image (a PNG or a JPEG) or one clip (a GIF or an MP4): say what it is, then send its parts, optionally a preview, and finish it. The answer says how many parts to send; every part but the last is 2,000,000 bytes. On a workspace with a storage allowance, an item that would take it over is refused here with 413 storage_full, before any part is sent; from here on its bytes count as used until it is deleted. An item that is not finished is removed after 24 hours. A workspace starts at most 60 items an hour.\"\n      operationId: createMedia\n      security: *a1\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/MediaCreate\"\n      responses:\n        \"201\":\n          description: The item exists. Send its parts.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/MediaCreated\"\n        \"400\":\n          description: The body is not a JSON object, or a field breaks its rule; the detail names it.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"413\":\n          description: \"too_large: the request body is too long. media_too_large: the item is larger than this server takes, and the answer carries the limits. storage_full: the item would take the workspace over its storage allowance; nothing was stored. Deleting tours or items, or a larger allowance, makes room.\"\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - type: object\n                    required:\n                      - error\n                      - detail\n                    properties:\n                      error:\n                        type: string\n                        enum:\n                          - too_large\n                      detail:\n                        type: string\n                    additionalProperties: false\n                  - $ref: \"#/components/schemas/MediaTooLarge\"\n                  - $ref: \"#/components/schemas/StorageFull\"\n        \"429\":\n          description: This workspace already started 60 items in the last hour.\n          headers: &a8\n            retry-after:\n              description: Seconds until the count starts again.\n              schema:\n                type: integer\n                minimum: 1\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_many_items\n                  detail:\n                    type: string\n                additionalProperties: false\n    get:\n      tags:\n        - Items\n      summary: List the workspace's shared items\n      description: The finished items of the workspace of one kind, newest first, 50 at a time. Ask with the query kind=image or kind=clip; for the next page add cursor= with the next of the previous answer. Items that are not finished are not listed.\n      operationId: listMedia\n      security: *a1\n      responses:\n        \"200\":\n          description: One page of items.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/MediaList\"\n        \"400\":\n          description: \"bad_request: kind is missing or not image or clip. bad_cursor: the cursor is not one this list gave.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_cursor\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n  /api/v1/media/{id}:\n    get:\n      tags:\n        - Items\n      summary: Get one shared item\n      description: One item of the workspace, finished or not, with its state.\n      operationId: getMedia\n      security: *a1\n      parameters:\n        - &a7\n          name: id\n          in: path\n          required: true\n          description: The item's id, from the answer that started it.\n          schema:\n            type: string\n            pattern: ^med_[0-9a-f]{24}$\n      responses:\n        \"200\":\n          description: The item.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/MediaItemState\"\n        \"401\": *a2\n        \"404\":\n          description: \"No such item in this workspace: unknown, another workspace's, or being deleted.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n    delete:\n      tags:\n        - Items\n      summary: Delete a shared item\n      description: \"Removes an item, finished or not, with every part and its preview. Its bytes stop counting at once, and its public address stops working. When some files could not be removed yet, the answer is 500 cleanup_pending: send the same request again.\"\n      operationId: deleteMedia\n      security: *a1\n      parameters:\n        - *a7\n      responses:\n        \"204\":\n          description: Nothing of the item is left.\n        \"401\": *a2\n        \"404\":\n          description: \"No such item in this workspace: unknown, another workspace's, or being deleted, or already deleted.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"500\":\n          description: The item is deleted, but some of its files could not be removed yet. Send the same request again.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - cleanup_pending\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/media/{id}/parts/{n}:\n    put:\n      tags:\n        - Items\n      summary: Send one part of an item\n      description: \"The body is part n of the file, as bytes: 2,000,000 bytes for every part but the last, which holds the rest. Part 0 must start like a file of the declared type, read from its own bytes, and for a PNG, JPEG or GIF its width and height must be the declared ones; an MP4's size and duration are taken as declared. Parts may be sent in any order; sending one again replaces it.\"\n      operationId: putMediaPart\n      security: *a1\n      parameters:\n        - *a7\n        - name: n\n          in: path\n          required: true\n          description: The part's number, counted from 0.\n          schema:\n            type: integer\n            minimum: 0\n            maximum: 998\n      requestBody:\n        required: true\n        content:\n          application/octet-stream:\n            schema:\n              type: string\n              format: binary\n      responses:\n        \"204\":\n          description: The part is stored.\n        \"400\":\n          description: \"bad_part: the part's length is not the one it must have. bad_media: part 0 is not a file of the declared type, or its width and height differ from the declared ones.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_part\n                      - bad_media\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\":\n          description: \"No such item in this workspace: unknown, another workspace's, or being deleted, or the item has no part of that number.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"409\":\n          description: The item is finished; its parts cannot change.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - already_online\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: The part is too long.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - too_large\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/media/{id}/preview:\n    put:\n      tags:\n        - Items\n      summary: Send an item's preview\n      description: \"Optional: a small picture that stands for the item in lists, a PNG or a JPEG of at most 100,000 bytes and 512 pixels on a side, read from its own bytes. Send it before the item is finished; a new one replaces the old. Its size counts against the storage allowance.\"\n      operationId: putMediaPreview\n      security: *a1\n      parameters:\n        - *a7\n      requestBody:\n        required: true\n        content: *a5\n      responses:\n        \"204\":\n          description: The preview is stored.\n        \"400\":\n          description: The body is not a PNG or JPEG within the preview's size.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_image\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"404\":\n          description: \"No such item in this workspace: unknown, another workspace's, or being deleted.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"409\":\n          description: The item is finished; its preview cannot change.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - already_online\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"413\":\n          description: \"too_large: the preview is too long. storage_full: it would take the workspace over its storage allowance; nothing was stored.\"\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - type: object\n                    required:\n                      - error\n                      - detail\n                    properties:\n                      error:\n                        type: string\n                        enum:\n                          - too_large\n                      detail:\n                        type: string\n                    additionalProperties: false\n                  - $ref: \"#/components/schemas/StorageFull\"\n    get:\n      tags:\n        - Items\n      summary: Get an item's preview\n      description: The item's preview picture, to its own workspace, as the type read from its bytes when it was sent.\n      operationId: getMediaPreview\n      security: *a1\n      parameters:\n        - *a7\n      responses:\n        \"200\":\n          description: The preview.\n          content: *a5\n        \"401\": *a2\n        \"404\":\n          description: \"No such item in this workspace: unknown, another workspace's, or being deleted, or it has no preview.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/media/{id}/commit:\n    post:\n      tags:\n        - Items\n      summary: Finish a shared item\n      description: Checks that every part is stored and that they add up to the declared bytes, and puts the item online at its public address. From then on it does not change until it is deleted. A repeated request answers the same.\n      operationId: commitMedia\n      security: *a1\n      parameters:\n        - *a7\n      responses:\n        \"200\":\n          description: The item is online.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/MediaCommitted\"\n        \"401\": *a2\n        \"404\":\n          description: \"No such item in this workspace: unknown, another workspace's, or being deleted.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"409\":\n          description: A part has not been sent or is still being sent, the parts do not add up to the declared bytes, or the preview is still being sent; the detail says which. Nothing changes.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - incomplete\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/me:\n    get:\n      tags:\n        - Workspace\n      summary: The workspace and the server version\n      description: \"The name of the token's workspace and the version of the server: the request to test a connection with. On a server with two addresses the answer also has addresses, the two host names.\"\n      operationId: getMe\n      security: *a1\n      responses:\n        \"200\":\n          description: The workspace and the version.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Me\"\n        \"401\": *a2\n        \"404\":\n          description: The token's workspace no longer exists.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/usage:\n    get:\n      tags:\n        - Workspace\n      summary: The workspace's storage use\n      description: \"What the token's workspace uses of its storage allowance, in bytes. Counted: the image of every step of every tour, published or not; each tour's logo; and the room held by every upload that is not finished (its images as the manifest gives them, and for a logo it carries the logo_bytes it was started with, or 200,000 bytes without, until the logo's real size is recorded when the upload is finished), until the upload is finished, cancelled or removed. An upload nobody finishes is not removed by the clock alone: it is removed when the workspace next starts an upload once it is more than 24 hours old, and until then its room is still counted here. Not counted: the copies of images a published tour serves, and files that wait to be removed after a delete or a replace. allowance_bytes is null when neither the server's settings nor the workspace has one: No limit. over is true when more is used than the allowance, which can happen when an allowance is lowered; the server never deletes or unpublishes anything because of it, and only starting an upload that needs room is refused.\"\n      operationId: getUsage\n      security: *a1\n      responses:\n        \"200\":\n          description: The workspace's numbers.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Usage\"\n        \"401\": *a2\n  /api/v1/usage/largest:\n    get:\n      tags:\n        - Workspace\n      summary: The workspace's ten largest tours\n      description: The 10 largest tours of the token's workspace, largest first, each with its id, its title and its size in bytes as the tour list gives it (its steps' images and its logo, as GET /api/v1/usage counts them). Tours of the same size come in the order of their id. Fewer when the workspace has fewer tours; none for an empty one.\n      operationId: getLargestTours\n      security: *a1\n      responses:\n        \"200\":\n          description: The largest tours.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/LargestTours\"\n        \"401\": *a2\n  /api/v1/signin/request:\n    post:\n      tags:\n        - Accounts\n      summary: Ask for a sign-in link\n      description: Mails a sign-in link to the address, when it belongs to an account that may sign in, the site has an admin and mail is on. The answer is the same in every case, so it does not tell whether the address has an account, and it does not wait for the mail. The link works once and for 15 minutes. Needs no credential, but must come from a page of the address it is sent to, as JSON. One address gets at most a few links in a quarter hour and in a day; past that the answer is the same and no mail is sent.\n      operationId: requestSignInLink\n      security: []\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/SignInRequest\"\n      responses:\n        \"200\":\n          description: The same for every well-formed address.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Ok\"\n        \"400\":\n          description: \"bad_request: the body is not a JSON object sent as application/json. bad_email, with no detail: email is not an email address.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_email\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"403\":\n          description: \"The request did not come from a page of this address: no Origin, another one, or the browser says it came from another site.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_origin\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"429\":\n          description: Too many requests from this network. Nothing was sent.\n          headers: *a8\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - rate_limited\n                additionalProperties: false\n  /api/v1/signin/complete:\n    post:\n      tags:\n        - Accounts\n      summary: Finish signing in\n      description: Turns the code of a sign-in link into a session, once, and sets the session cookie on this address. A session the browser already had ends. Needs no credential, but must come from a page of the address it is sent to, as JSON. A code that is unknown, already used, expired or of an account that may not sign in gets the one answer link_invalid. The answer never repeats the code.\n      operationId: completeSignIn\n      security: []\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/SignInComplete\"\n      responses:\n        \"200\":\n          description: Signed in.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Ok\"\n          headers:\n            set-cookie:\n              description: \"The session cookie: host-only, Secure, HttpOnly and SameSite=Lax.\"\n              schema:\n                type: string\n                pattern: ^__Host-dp_session=\n        \"400\":\n          description: \"bad_request: the body is not a JSON object sent as application/json. bad_code, with no detail: code is not a sign-in code.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_code\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"403\":\n          description: \"bad_origin: the request did not come from a page of this address. link_invalid: the link has expired or was already used; ask for a new one.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_origin\n                      - link_invalid\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"429\":\n          description: Too many tries from this network. Nothing was looked at.\n          headers: *a8\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - rate_limited\n                additionalProperties: false\n  /api/v1/session:\n    get:\n      tags:\n        - Accounts\n      summary: The session and who it is\n      description: The account, its workspace and this session, and the anti-forgery value a change made with the session needs. Sets the session cookie again. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\n      operationId: getSession\n      security: &a9\n        - session: []\n      responses:\n        \"200\":\n          description: The session.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Session\"\n          headers:\n            set-cookie:\n              description: The same session cookie again.\n              schema:\n                type: string\n                pattern: ^__Host-dp_session=\n        \"401\": *a2\n  /api/v1/sessions:\n    get:\n      tags:\n        - Accounts\n      summary: List the account's sessions\n      description: Every live session of the caller's own account, where it is signed in, with the current one first and marked. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\n      operationId: listSessions\n      security: *a9\n      responses:\n        \"200\":\n          description: The sessions.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/SessionList\"\n        \"401\": *a2\n  /api/v1/sessions/{id}:\n    delete:\n      tags:\n        - Accounts\n      summary: End one of the account's sessions\n      description: Ends one session of the caller's own account, such as one in another browser; the cookie is not touched. Another account's session answers 404, the same as one that does not exist. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\n      operationId: endSession\n      security: *a9\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: The session's id, as the list of sessions gives it.\n          schema:\n            type: string\n            pattern: ^ses_[0-9a-f]{24}$\n      responses:\n        \"204\":\n          description: The session has ended.\n        \"401\": *a2\n        \"404\":\n          description: No such live session of this account.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/signout:\n    post:\n      tags:\n        - Accounts\n      summary: Sign out\n      description: Ends the session the request is sent with and clears its cookie. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\n      operationId: signOut\n      security: *a9\n      responses:\n        \"204\":\n          description: Signed out.\n          headers:\n            set-cookie:\n              description: Clears the session cookie.\n              schema:\n                type: string\n                pattern: ^__Host-dp_session=\n        \"401\": *a2\n  /api/v1/signout/everywhere:\n    post:\n      tags:\n        - Accounts\n      summary: Sign out everywhere\n      description: Ends every session of the caller's account, in every browser, and clears this one's cookie. Tokens keep working. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\n      operationId: signOutEverywhere\n      security: *a9\n      responses:\n        \"204\":\n          description: Every session of the account has ended.\n          headers:\n            set-cookie:\n              description: Clears the session cookie.\n              schema:\n                type: string\n                pattern: ^__Host-dp_session=\n        \"401\": *a2\n  /api/v1/account/email:\n    post:\n      tags:\n        - Accounts\n      summary: Ask to change the email address\n      description: Mails a link to the new address; the account's address changes only when that link is opened (POST /api/v1/account/email/confirm), once and within 15 minutes. Asking again replaces the earlier link. The answer is the same whether the new address is free, belongs to another account or is the account's own, so it does not tell who has an account; only a free address is sent a link, and no other mail is sent. It does not wait for the mail. Each account, each account for one address, and each address from all accounts together, can be asked for only a few times in a quarter hour and in a day; an account that asks too often for one address limits only itself, not others asking for it. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\n      operationId: requestEmailChange\n      security: *a9\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/EmailChangeRequest\"\n      responses:\n        \"200\":\n          description: The same for every well-formed address.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Ok\"\n        \"400\":\n          description: \"bad_request: the body is not a JSON object sent as application/json. bad_email, with no detail: email is not an email address.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_email\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"409\":\n          description: This site cannot send mail, so the address cannot be changed here. Nothing was stored.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - mail_off\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"429\":\n          description: Too many requests for this account or this address. Nothing was stored or sent.\n          headers: *a8\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - rate_limited\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/account/email/confirm:\n    post:\n      tags:\n        - Accounts\n      summary: Finish changing the email address\n      description: \"Makes the change the code of the link names, once: the account's address becomes the new one, its open sign-in links stop working, and the old address is sent a notice that shows the new one partly hidden. It must be sent with a session of the account that asked. The account stays signed in everywhere. A code that is unknown, already used, more than 15 minutes old, replaced by a later request or of another account, and one for an address another account has taken since, all get the one answer bad_code. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\"\n      operationId: confirmEmailChange\n      security: *a9\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/EmailChangeConfirm\"\n      responses:\n        \"200\":\n          description: The address was changed.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/EmailChanged\"\n        \"400\":\n          description: \"bad_request: the body is not a JSON object sent as application/json. bad_code: the link no longer works; ask for a new one.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_code\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"401\": *a2\n        \"429\":\n          description: Too many tries for this account. Nothing was looked at.\n          headers: *a8\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - rate_limited\n                  detail:\n                    type: string\n                additionalProperties: false\n  /api/v1/admin/summary:\n    get:\n      tags:\n        - Admin\n      summary: Every account's storage use in all\n      description: \"For the site's admin: how many accounts there are, what all their workspaces use together (counted as GET /api/v1/usage counts it for each account itself) and the site's standard allowance, null when the server's settings set none. Nothing of any workspace is in it. Every refusal is the one 404, whoever asks and whatever is wrong with the request. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\"\n      operationId: adminSummary\n      security: *a9\n      responses:\n        \"200\":\n          description: The three numbers.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/AdminSummary\"\n        \"404\":\n          description: \"Anything other than the site's admin, signed in on this address, with a correct request: no credential, a token, another account's session, a token with a session, or a session on the tours address. The 400 and 403 answers any request can get are this 404 here.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                additionalProperties: false\n  /api/v1/admin/accounts:\n    get:\n      tags:\n        - Admin\n      summary: List every account's storage use\n      description: \"For the site's admin: every account, in the order they were made, 100 at a time, with its workspace's id and name, its tour count, what it uses of its storage (counted as GET /api/v1/usage counts it for the account itself) and its allowance. Nothing of any workspace's tours is in it. Add ?after=<id>, with the next of the previous answer, for the next page. Every refusal is the one 404, whoever asks and whatever is wrong with the request. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\"\n      operationId: adminListAccounts\n      security: *a9\n      responses:\n        \"200\":\n          description: The accounts.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/AdminAccountList\"\n        \"400\":\n          description: after is not the id of an account.\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"404\":\n          description: \"Anything other than the site's admin, signed in on this address, with a correct request: no credential, a token, another account's session, a token with a session, or a session on the tours address. The 400 and 403 answers any request can get are this 404 here.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                additionalProperties: false\n  /api/v1/admin/workspaces/{id}:\n    patch:\n      tags:\n        - Admin\n      summary: Set a workspace's storage allowance\n      description: \"For the site's admin: sets the workspace's storage allowance in bytes, or with null goes back to the site's default (the server's setting). The change is in the audit record with the old and the new number. An allowance below what the workspace already uses is taken: nothing is deleted or unpublished, and only starting an upload that needs more room is refused from then on. Every refusal of the caller or of the request's origin, and a workspace that does not exist, is the one 404. It needs the session cookie, so it cannot be tried from the documentation page, which never sends a cookie.\"\n      operationId: adminSetAllowance\n      security: *a9\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: The workspace's id, as the list of accounts gives it in workspace_id.\n          schema:\n            type: string\n            pattern: ^ws_[0-9a-f]{24}$\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/AllowanceChange\"\n      responses:\n        \"200\":\n          description: The workspace's numbers after the change.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/AllowanceSet\"\n        \"400\":\n          description: \"bad_request: the body is not a JSON object holding storage_allowance_bytes and nothing else. bad_allowance: the value is not a whole number of bytes from 0 to 9007199254740991, or null for the site's default.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                  - detail\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - bad_request\n                      - bad_allowance\n                  detail:\n                    type: string\n                additionalProperties: false\n        \"404\":\n          description: \"No such workspace, or anything other than the site's admin, signed in on this address, with a correct request: no credential, a token, another account's session, a token with a session, a session on the tours address, a change from another origin or without the anti-forgery header. The 400 and 403 answers any request can get are this 404 here.\"\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - error\n                properties:\n                  error:\n                    type: string\n                    enum:\n                      - not_found\n                additionalProperties: false\n  /healthz:\n    get:\n      tags:\n        - Server\n      summary: Whether the server is up\n      description: Answers 200 when the server runs and reaches its database. It needs no token and answers on every host name. On a server with two addresses, asked on one of them, it also says which of the two it was reached on.\n      operationId: getHealth\n      security: []\n      responses:\n        \"200\":\n          description: The server is up.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Health\"\ncomponents:\n  securitySchemes:\n    token:\n      type: http\n      scheme: bearer\n    session:\n      type: apiKey\n      in: cookie\n      name: __Host-dp_session\n  schemas:\n    Error:\n      type: object\n      description: The shape of every refusal. Each request lists the codes it can answer.\n      required:\n        - error\n      properties:\n        error:\n          type: string\n          description: A stable code, such as not_found.\n        detail:\n          type: string\n          description: The reason in plain words. The text may change; do not match on it.\n      additionalProperties: false\n    Unauthorized:\n      type: object\n      description: The one answer for a missing, malformed, unknown, expired or revoked token or session.\n      required:\n        - error\n      properties:\n        error:\n          type: string\n          const: unauthorized\n      additionalProperties: false\n    InProgress:\n      type: object\n      description: A delete that has more to do. Send the same request again.\n      required:\n        - status\n        - done\n        - total\n      properties:\n        status: &a10\n          type: string\n          const: in_progress\n        done:\n          type: integer\n          minimum: 0\n          description: Files removed so far.\n        total:\n          type: integer\n          minimum: 0\n          description: Files to remove in all.\n      additionalProperties: false\n    PublishInProgress:\n      type: object\n      description: A publish that has more images to copy.\n      required:\n        - status\n        - publish_id\n        - done\n        - total\n      properties:\n        status: *a10\n        publish_id:\n          type: string\n          pattern: ^pub_[0-9a-f]{24}$\n          description: Send it back in the next publish request to continue this publish.\n        done:\n          type: integer\n          minimum: 0\n          description: Images copied so far.\n        total:\n          type: integer\n          minimum: 0\n          description: Images to copy in all.\n      additionalProperties: false\n    UnpublishInProgress:\n      type: object\n      description: The tour is unpublished, but some of its public images are still to be removed. Send the same request again.\n      required:\n        - status\n        - detail\n      properties:\n        status: *a10\n        detail:\n          type: string\n          description: What is left to do, in plain words.\n      additionalProperties: false\n    Tour:\n      type: object\n      required:\n        - id\n        - title\n        - status\n        - slug\n        - url\n        - chapters\n        - steps\n        - bytes\n        - updated_at\n        - published_at\n        - unpublished_changes\n      properties:\n        id:\n          type: string\n          pattern: ^tour_[0-9a-f]{24}$\n        title:\n          type: string\n        status:\n          type: string\n          enum:\n            - draft\n            - published\n        slug:\n          type: string\n          description: The last part of the public link. It never changes, also not on a rename.\n        url:\n          type:\n            - string\n            - \"null\"\n          description: The public link as a path, /t/<slug>, to put after the server address. null for a draft.\n        chapters:\n          type: integer\n          minimum: 0\n          description: How many chapters the draft has.\n        steps:\n          type: integer\n          minimum: 0\n          description: How many steps the draft has.\n        bytes:\n          type: integer\n          minimum: 0\n          description: \"The tour's size in bytes, counted as GET /api/v1/usage counts storage: the images of all its steps and its logo (a logo stored by a server before version 0.1.8 counts as 0). Over all of a workspace's tours these add up to the usage's pictures and logos; uploads that are not finished belong to no tour and are not in it.\"\n        updated_at:\n          type: integer\n          minimum: 0\n          description: When the draft last changed, in milliseconds since 1970.\n        published_at:\n          type:\n            - integer\n            - \"null\"\n          description: When the tour was last published, in milliseconds since 1970. null for a draft.\n        unpublished_changes:\n          type: boolean\n          description: true when the tour is published and its draft holds a chapter upload or update that is not on the public page yet, so publishing it again would change what visitors see; also when the server cannot tell, which happens only for some tours last published before version 0.1.4. false for a draft, and for a published tour whose page is up to date. A rename is live at once and never sets it.\n      additionalProperties: false\n    TourList:\n      type: object\n      required:\n        - tours\n      properties:\n        tours:\n          type: array\n          items:\n            $ref: \"#/components/schemas/Tour\"\n          description: Most recently changed first.\n      additionalProperties: false\n    RenameBody:\n      type: object\n      required:\n        - title\n      properties:\n        title:\n          type: string\n          minLength: 1\n          maxLength: 200\n          description: \"The new title: trimmed, no control or format characters.\"\n    Renamed:\n      type: object\n      required:\n        - id\n        - title\n      properties:\n        id:\n          type: string\n        title:\n          type: string\n          description: The title as saved (trimmed).\n      additionalProperties: false\n    Deleted:\n      type: object\n      description: Nothing of the tour is left.\n      required:\n        - deleted\n      properties:\n        deleted:\n          type: boolean\n          const: true\n      additionalProperties: false\n    PublishBody:\n      type: object\n      required: []\n      properties:\n        publish_id:\n          type:\n            - string\n            - \"null\"\n          pattern: ^pub_[0-9a-f]{24}$\n          description: The publish_id of the previous answer, to continue that publish.\n    Published:\n      type: object\n      description: The new version is live.\n      required:\n        - slug\n        - url\n        - steps\n      properties:\n        slug:\n          type: string\n        url:\n          type: string\n          description: The tour's link as a path, /t/<slug>, to put after the server address.\n        steps:\n          type: integer\n          minimum: 0\n          description: How many steps the published version has.\n      additionalProperties: false\n    Me:\n      type: object\n      required:\n        - workspace\n        - version\n      properties:\n        workspace:\n          type: string\n          description: The workspace's name.\n        version:\n          type: string\n          description: The server's version.\n        addresses:\n          type: object\n          description: \"Only on a server with two addresses: both host names, without a scheme. Absent means: use the address you were given.\"\n          required:\n            - tours\n            - app\n          properties:\n            tours:\n              type: string\n              description: The host name tour links use.\n            app:\n              type: string\n              description: The host name of the app address.\n          additionalProperties: false\n      additionalProperties: false\n    Usage:\n      type: object\n      description: What a workspace uses of its storage allowance.\n      required:\n        - used_bytes\n        - allowance_bytes\n        - over\n        - tours\n        - counted\n      properties:\n        used_bytes:\n          type: integer\n          minimum: 0\n          description: \"What the workspace uses, in bytes: the three numbers of counted together.\"\n        allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          description: \"The workspace's storage allowance in bytes: its own number, else the server's setting. null when there is no limit.\"\n        over:\n          type: boolean\n          description: true when more is used than the allowance. Always false without a limit; exactly the allowance is not over it.\n        tours:\n          type: integer\n          minimum: 0\n          description: How many tours the workspace has, drafts and published.\n        counted:\n          type: object\n          description: What used_bytes is made of, in bytes.\n          required:\n            - pictures\n            - logos\n            - uploads_in_progress\n          properties:\n            pictures:\n              type: integer\n              minimum: 0\n              description: The images of every step of every tour, published or not.\n            logos:\n              type: integer\n              minimum: 0\n              description: The tours' logos. A logo stored by a server before version 0.1.8 counts as 0.\n            uploads_in_progress:\n              type: integer\n              minimum: 0\n              description: \"The room held by uploads that are not finished: what each one needed when it was started.\"\n          additionalProperties: false\n      additionalProperties: false\n    LargestTours:\n      type: object\n      required:\n        - tours\n      properties:\n        tours:\n          type: array\n          maxItems: 10\n          description: At most 10, largest first; tours of the same size in the order of their ids.\n          items:\n            type: object\n            required:\n              - id\n              - title\n              - bytes\n            properties:\n              id:\n                type: string\n                pattern: ^tour_[0-9a-f]{24}$\n              title:\n                type: string\n              bytes:\n                type: integer\n                minimum: 0\n                description: The tour's size in bytes, as the tour list gives it.\n            additionalProperties: false\n      additionalProperties: false\n    StorageFull:\n      type: object\n      description: The upload, shared item or preview would take the workspace over its storage allowance. Nothing was stored, and no upload or item exists that this request made.\n      required:\n        - error\n        - detail\n        - used_bytes\n        - allowance_bytes\n        - needed_bytes\n      properties:\n        error:\n          type: string\n          enum:\n            - storage_full\n        detail:\n          type: string\n          description: 'The same in words, as one sentence under 200 characters that a program can show after its own words, such as \"Could not start the upload: \". The text may change; do not match on it.'\n        used_bytes:\n          type: integer\n          minimum: 0\n          description: What the workspace uses now, in bytes.\n        allowance_bytes:\n          type: integer\n          minimum: 0\n          description: The workspace's storage allowance, in bytes.\n        needed_bytes:\n          type: integer\n          minimum: 0\n          description: \"The room this upload needs, in bytes: all its images, and for a logo it carries its logo_bytes, or 200,000 without one; for the replacement of a chapter, only what that comes to above the chapter's present images and, for a tour's first chapter, the recorded size of its present logo. For a shared item, its bytes; for an item's preview, what its size comes to above the preview it replaces.\"\n      additionalProperties: false\n    MediaCreate:\n      type: object\n      required:\n        - kind\n        - content_type\n        - bytes\n        - width\n        - height\n      properties:\n        kind:\n          type: string\n          enum:\n            - image\n            - clip\n          description: An image (a PNG or a JPEG) or a clip (a GIF or an MP4).\n        content_type:\n          type: string\n          enum:\n            - image/png\n            - image/jpeg\n            - image/gif\n            - video/mp4\n          description: image/png or image/jpeg for an image, image/gif or video/mp4 for a clip. Part 0 must be a file of this type.\n        bytes:\n          type: integer\n          minimum: 1\n          description: \"The file's length in bytes: at most 10,485,760 for an image and 52,428,800 for a clip, unless the server's settings give other numbers.\"\n        width:\n          type: integer\n          minimum: 1\n          description: \"In pixels: at most 8,192 for an image, unless the server's settings give another number, and 8,192 for a clip. For a PNG, JPEG or GIF it must be what the file says.\"\n        height:\n          type: integer\n          minimum: 1\n          description: In pixels, as width.\n        duration_ms:\n          type: integer\n          minimum: 1\n          maximum: 600000\n          description: How long the clip runs, in milliseconds. Required for a clip; leave it out for an image. Shown as given.\n        title:\n          type:\n            - string\n            - \"null\"\n          maxLength: 120\n          description: \"Optional: at most 120 characters after trimming, no control or format characters. Empty is no title.\"\n    MediaCreated:\n      type: object\n      required:\n        - id\n        - parts\n        - part_bytes\n      properties:\n        id:\n          type: string\n          pattern: ^med_[0-9a-f]{24}$\n        parts:\n          type: integer\n          minimum: 1\n          description: How many parts to send, numbered from 0.\n        part_bytes:\n          type: integer\n          minimum: 1\n          description: \"The length of every part but the last, which holds the rest: 2,000,000.\"\n      additionalProperties: false\n    MediaCommitted:\n      type: object\n      required:\n        - id\n        - link_id\n        - kind\n        - path\n        - link\n      properties:\n        id:\n          type: string\n          pattern: ^med_[0-9a-f]{24}$\n        link_id:\n          type: string\n          pattern: ^[a-z2-7]{20}$\n          description: The item's public name. It never changes.\n        kind:\n          type: string\n          enum:\n            - image\n            - clip\n        path:\n          type: string\n          description: \"The item's public address as a path: /i/<link_id> for an image, /r/<link_id> for a clip.\"\n        link:\n          type: string\n          description: The item's public address in full.\n      additionalProperties: false\n    MediaItem:\n      type: object\n      required:\n        - id\n        - link_id\n        - kind\n        - title\n        - content_type\n        - bytes\n        - width\n        - height\n        - duration_ms\n        - created_at\n        - has_preview\n        - path\n        - link\n      properties:\n        id:\n          type: string\n          pattern: ^med_[0-9a-f]{24}$\n        link_id:\n          type: string\n          pattern: ^[a-z2-7]{20}$\n        kind:\n          type: string\n          enum:\n            - image\n            - clip\n        title:\n          type:\n            - string\n            - \"null\"\n        content_type:\n          type: string\n          enum:\n            - image/png\n            - image/jpeg\n            - image/gif\n            - video/mp4\n        bytes:\n          type: integer\n          minimum: 1\n          description: The file's length in bytes.\n        width:\n          type: integer\n          minimum: 1\n          description: In pixels.\n        height:\n          type: integer\n          minimum: 1\n          description: In pixels.\n        duration_ms:\n          type:\n            - integer\n            - \"null\"\n          description: A clip's duration in milliseconds, as given. null for an image.\n        created_at:\n          type: integer\n          minimum: 0\n          description: When the item was started, in milliseconds since 1970.\n        has_preview:\n          type: boolean\n          description: Whether a preview picture was sent.\n        path:\n          type: string\n          description: \"The public address as a path: /i/<link_id> or /r/<link_id>.\"\n        link:\n          type: string\n          description: The public address in full.\n      additionalProperties: false\n    MediaItemState:\n      type: object\n      required:\n        - id\n        - link_id\n        - kind\n        - title\n        - content_type\n        - bytes\n        - width\n        - height\n        - duration_ms\n        - created_at\n        - has_preview\n        - path\n        - link\n        - state\n      properties:\n        id:\n          type: string\n          pattern: ^med_[0-9a-f]{24}$\n        link_id:\n          type: string\n          pattern: ^[a-z2-7]{20}$\n        kind:\n          type: string\n          enum:\n            - image\n            - clip\n        title:\n          type:\n            - string\n            - \"null\"\n        content_type:\n          type: string\n          enum:\n            - image/png\n            - image/jpeg\n            - image/gif\n            - video/mp4\n        bytes:\n          type: integer\n          minimum: 1\n          description: The file's length in bytes.\n        width:\n          type: integer\n          minimum: 1\n          description: In pixels.\n        height:\n          type: integer\n          minimum: 1\n          description: In pixels.\n        duration_ms:\n          type:\n            - integer\n            - \"null\"\n          description: A clip's duration in milliseconds, as given. null for an image.\n        created_at:\n          type: integer\n          minimum: 0\n          description: When the item was started, in milliseconds since 1970.\n        has_preview:\n          type: boolean\n          description: Whether a preview picture was sent.\n        path:\n          type: string\n          description: \"The public address as a path: /i/<link_id> or /r/<link_id>.\"\n        link:\n          type: string\n          description: The public address in full.\n        state:\n          type: string\n          enum:\n            - uploading\n            - online\n          description: uploading until the item is finished, then online.\n      additionalProperties: false\n    MediaList:\n      type: object\n      required:\n        - items\n        - next\n      properties:\n        items:\n          type: array\n          maxItems: 50\n          items:\n            $ref: \"#/components/schemas/MediaItem\"\n          description: Newest first.\n        next:\n          type:\n            - string\n            - \"null\"\n          description: Send it as cursor for the next page. null on the last page.\n      additionalProperties: false\n    MediaTooLarge:\n      type: object\n      description: The item is larger than this server takes. Nothing was stored.\n      required:\n        - error\n        - detail\n        - max_bytes\n        - max_side\n      properties:\n        error:\n          type: string\n          enum:\n            - media_too_large\n        detail:\n          type: string\n          description: The same in words. The text may change; do not match on it.\n        max_bytes:\n          type: integer\n          minimum: 1\n          description: The most bytes an item of this kind may have here.\n        max_side:\n          type: integer\n          minimum: 1\n          description: The most pixels an item of this kind may have on a side.\n      additionalProperties: false\n    SignInRequest:\n      type: object\n      required:\n        - email\n      properties:\n        email:\n          type: string\n          minLength: 3\n          maxLength: 254\n          description: The address to send the link to. Spaces around it are dropped and capitals do not count.\n    SignInComplete:\n      type: object\n      required:\n        - code\n      properties:\n        code:\n          type: string\n          pattern: ^dpl_[0-9a-f]{40}$\n          description: \"The code of the link, the part after #c= in its address.\"\n    EmailChangeRequest:\n      type: object\n      required:\n        - email\n      properties:\n        email:\n          type: string\n          minLength: 3\n          maxLength: 254\n          description: The new address, which the link is mailed to. Spaces around it are dropped and capitals do not count.\n    EmailChangeConfirm:\n      type: object\n      required:\n        - code\n      properties:\n        code:\n          type: string\n          pattern: ^dpe_[0-9a-f]{40}$\n          description: \"The code of the link mailed to the new address, the part after #c= in its address.\"\n    EmailChanged:\n      type: object\n      description: The change was made.\n      required:\n        - email\n        - previous_email\n      properties:\n        email:\n          type: string\n          description: The account's address from now on.\n        previous_email:\n          type: string\n          description: The address it had, which was sent a notice.\n      additionalProperties: false\n    Ok:\n      type: object\n      required:\n        - ok\n      properties:\n        ok:\n          type: boolean\n          const: true\n      additionalProperties: false\n    Session:\n      type: object\n      required:\n        - account\n        - workspace\n        - session\n        - csrf\n        - email_change\n      properties:\n        account:\n          type: object\n          description: The account the session belongs to.\n          required:\n            - id\n            - username\n            - email\n            - admin\n          properties:\n            id:\n              type: string\n              pattern: ^usr_[0-9a-f]{24}$\n            username:\n              type:\n                - string\n                - \"null\"\n              description: null until the account has one.\n            email:\n              type: string\n            admin:\n              type: boolean\n              description: true for the site's admin.\n          additionalProperties: false\n        workspace:\n          type: object\n          description: The account's workspace, the one every request of the session acts in.\n          required:\n            - id\n            - name\n          properties:\n            id:\n              type: string\n              pattern: ^ws_[0-9a-f]{24}$\n            name:\n              type: string\n          additionalProperties: false\n        session:\n          type: object\n          description: This session.\n          required:\n            - id\n            - created_at\n            - expires_at\n          properties:\n            id:\n              type: string\n              pattern: ^ses_[0-9a-f]{24}$\n            created_at:\n              type: integer\n              minimum: 0\n              description: When the browser signed in, in milliseconds since 1970.\n            expires_at:\n              type: integer\n              minimum: 0\n              description: When the session ends unless it is used, in milliseconds since 1970.\n          additionalProperties: false\n        csrf:\n          type: string\n          pattern: ^[0-9a-f]{64}$\n          description: \"The anti-forgery value: send it in the X-Csrf-Token header of every change made with this session.\"\n        email_change:\n          type: boolean\n          description: true when the site can mail the link an email change needs; false when its mail is off, and POST /api/v1/account/email then answers mail_off.\n      additionalProperties: false\n    SessionList:\n      type: object\n      required:\n        - sessions\n      properties:\n        sessions:\n          type: array\n          description: The account's live sessions, the current one first.\n          items:\n            type: object\n            required:\n              - id\n              - label\n              - created_at\n              - last_used_at\n              - expires_at\n              - current\n            properties:\n              id:\n                type: string\n                pattern: ^ses_[0-9a-f]{24}$\n              label:\n                type: string\n                maxLength: 40\n                description: The browser and the system it was signed in on, such as Firefox on Linux, or Unknown browser.\n              created_at:\n                type: integer\n                minimum: 0\n                description: When it was signed in, in milliseconds since 1970.\n              last_used_at:\n                type: integer\n                minimum: 0\n                description: When it was last used, to the hour, in milliseconds since 1970.\n              expires_at:\n                type: integer\n                minimum: 0\n                description: When it ends unless it is used, in milliseconds since 1970.\n              current:\n                type: boolean\n                description: true for the session this request was sent with.\n            additionalProperties: false\n      additionalProperties: false\n    AdminAccount:\n      type: object\n      description: \"One account and how its workspace uses its storage. Nothing of the workspace's tours: no tour, title, link, picture, token or session.\"\n      required:\n        - id\n        - username\n        - email\n        - status\n        - admin\n        - created_at\n        - workspace_id\n        - workspace_name\n        - tours\n        - used_bytes\n        - allowance_bytes\n        - storage_allowance_bytes\n        - over\n        - counted\n      properties:\n        id:\n          type: string\n          pattern: ^usr_[0-9a-f]{24}$\n          description: The account's id.\n        username:\n          type:\n            - string\n            - \"null\"\n          description: null until the account has one.\n        email:\n          type: string\n          description: The address the account signs in with.\n        status:\n          type: string\n          enum:\n            - active\n            - disabled\n          description: \"disabled: the account cannot sign in, and its workspace's tokens are refused.\"\n        admin:\n          type: boolean\n          description: true for the site's admin.\n        created_at:\n          type: integer\n          minimum: 0\n          description: When the account was made, in milliseconds since 1970.\n        workspace_id:\n          type: string\n          pattern: ^ws_[0-9a-f]{24}$\n          description: \"The account's workspace: the id to set its allowance with.\"\n        workspace_name:\n          type: string\n          description: \"The workspace's name, as its owner wrote it. Show it as text: it may hold any characters.\"\n        tours:\n          type: integer\n          minimum: 0\n          description: How many tours the workspace has, drafts and published.\n        used_bytes:\n          type: integer\n          minimum: 0\n          description: What the workspace uses, in bytes, counted as GET /api/v1/usage counts it for the account itself.\n        allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          description: \"The allowance in force, in bytes: the workspace's own number, else the server's setting. null when there is no limit.\"\n        storage_allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          description: The workspace's own number, in bytes. null when it has none and the site's default applies.\n        over:\n          type: boolean\n          description: true when more is used than the allowance in force.\n        counted:\n          type: object\n          description: What used_bytes is made of, in bytes, as in GET /api/v1/usage.\n          required:\n            - pictures\n            - logos\n            - uploads_in_progress\n          properties:\n            pictures:\n              type: integer\n              minimum: 0\n              description: The images of every step of every tour.\n            logos:\n              type: integer\n              minimum: 0\n              description: The tours' logos.\n            uploads_in_progress:\n              type: integer\n              minimum: 0\n              description: The room held by uploads that are not finished.\n          additionalProperties: false\n      additionalProperties: false\n    AdminSummary:\n      type: object\n      description: The site's storage in all. Three numbers, nothing of any workspace.\n      required:\n        - accounts\n        - used_bytes\n        - standard_allowance_bytes\n      properties:\n        accounts:\n          type: integer\n          minimum: 0\n          description: How many accounts the site has.\n        used_bytes:\n          type: integer\n          minimum: 0\n          description: \"What all workspaces use together, in bytes: the sum of every account's used_bytes in the list of accounts.\"\n        standard_allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          description: \"The site's standard allowance from the server's settings, in bytes, which every workspace without a number of its own has. null when none is set: no limit.\"\n      additionalProperties: false\n    AdminAccountList:\n      type: object\n      required:\n        - accounts\n        - next\n      properties:\n        accounts:\n          type: array\n          maxItems: 100\n          description: The accounts, in the order they were made, at most 100.\n          items:\n            $ref: \"#/components/schemas/AdminAccount\"\n        next:\n          type:\n            - string\n            - \"null\"\n          pattern: ^usr_[0-9a-f]{24}$\n          description: The id to ask for the next page with, as ?after=<id>. null on the last page.\n      additionalProperties: false\n    AllowanceChange:\n      type: object\n      required:\n        - storage_allowance_bytes\n      properties:\n        storage_allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          minimum: 0\n          maximum: 9007199254740991\n          description: The workspace's allowance in bytes, or null to go back to the site's default.\n      additionalProperties: false\n    AllowanceSet:\n      type: object\n      required:\n        - workspace_id\n        - allowance_bytes\n        - storage_allowance_bytes\n        - used_bytes\n        - over\n      properties:\n        workspace_id:\n          type: string\n          pattern: ^ws_[0-9a-f]{24}$\n        allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          description: The allowance now in force, in bytes. null when there is no limit.\n        storage_allowance_bytes:\n          type:\n            - integer\n            - \"null\"\n          description: The workspace's own number as just set. null when the site's default applies.\n        used_bytes:\n          type: integer\n          minimum: 0\n          description: What the workspace uses, in bytes.\n        over:\n          type: boolean\n          description: \"true when the workspace uses more than its new allowance. Nothing is deleted: only uploads that need room are refused.\"\n      additionalProperties: false\n    Health:\n      type: object\n      required:\n        - ok\n      properties:\n        ok:\n          type: boolean\n          const: true\n        address:\n          type: string\n          enum:\n            - tours\n            - app\n            - img\n          description: \"Only on a server with two addresses (or three, with the optional img address), when asked on one of them: which one this request reached.\"\n      additionalProperties: false\n    UploadTarget:\n      description: Where the upload goes.\n      oneOf:\n        - $ref: \"#/components/schemas/TargetNew\"\n        - $ref: \"#/components/schemas/TargetChapter\"\n        - $ref: \"#/components/schemas/TargetReplace\"\n    TargetNew:\n      type: object\n      description: A new tour, made of this one chapter.\n      required:\n        - kind\n      properties:\n        kind:\n          type: string\n          const: new\n    TargetChapter:\n      type: object\n      description: A new chapter at the end of an existing tour. The tour keeps its settings and logo.\n      required:\n        - kind\n        - tour_id\n      properties:\n        kind:\n          type: string\n          const: chapter\n        tour_id:\n          type: string\n          pattern: ^tour_[0-9a-f]{24}$\n    TargetReplace:\n      type: object\n      description: Replaces one chapter of an existing tour. The chapter keeps its id, title and position and gets exactly the manifest's steps.\n      required:\n        - kind\n        - tour_id\n        - chapter_id\n      properties:\n        kind:\n          type: string\n          const: replace\n        tour_id:\n          type: string\n          pattern: ^tour_[0-9a-f]{24}$\n        chapter_id:\n          type: string\n          pattern: ^ch_[0-9a-f]{24}$\n    UploadCreate:\n      type: object\n      required:\n        - manifest\n        - target\n      properties:\n        manifest:\n          $ref: \"#/components/schemas/Manifest\"\n        target:\n          $ref: \"#/components/schemas/UploadTarget\"\n        sha256:\n          type: array\n          maxItems: 200\n          items:\n            type: string\n            pattern: ^[0-9a-f]{64}$\n          description: \"Only with the target replace, and optional: one SHA-256 per step of the manifest, in order, of the image the client would send. The answer's have then lists the steps not to send.\"\n        logo_bytes:\n          type: integer\n          minimum: 1\n          maximum: 200000\n          description: \"Optional: the length in bytes of the logo this upload will send. It counts only for an upload that takes a logo (a new tour, or the replacement of a tour's first chapter) and whose manifest names one; any other upload ignores it. The logo sent must then have exactly this length, and on a workspace with a storage allowance the upload needs this much room for the logo. Without it a logo of any allowed length is taken, and the upload needs 200,000 bytes of room for it.\"\n    UploadCreated:\n      type: object\n      description: The answer for the targets new and chapter.\n      required:\n        - upload_id\n        - steps\n      properties:\n        upload_id:\n          type: string\n          pattern: ^up_[0-9a-f]{24}$\n        steps:\n          type: integer\n          minimum: 1\n          description: How many step images the upload expects.\n      additionalProperties: false\n    ReplaceCreated:\n      type: object\n      description: The answer for the target replace.\n      required:\n        - upload_id\n        - steps\n        - have\n        - settings\n      properties:\n        upload_id:\n          type: string\n          pattern: ^up_[0-9a-f]{24}$\n        steps:\n          type: integer\n          minimum: 1\n          description: How many steps the manifest has.\n        have:\n          type: array\n          items:\n            type: integer\n            minimum: 1\n          description: The step numbers whose image the chapter already has; do not send them. Empty without sha256.\n        settings:\n          type: boolean\n          description: \"true when the chapter is the tour's first: the commit then also replaces the tour's settings and logo with the manifest's.\"\n      additionalProperties: false\n    Committed:\n      type: object\n      description: The answer for the targets new and chapter.\n      required:\n        - tour_id\n        - chapter_id\n        - steps\n      properties:\n        tour_id:\n          type: string\n          pattern: ^tour_[0-9a-f]{24}$\n        chapter_id:\n          type: string\n          pattern: ^ch_[0-9a-f]{24}$\n        steps:\n          type: integer\n          minimum: 0\n          description: How many steps the chapter has.\n      additionalProperties: false\n    ReplaceCommitted:\n      type: object\n      description: The answer for the target replace.\n      required:\n        - tour_id\n        - chapter_id\n        - steps\n        - publish\n      properties:\n        tour_id:\n          type: string\n          pattern: ^tour_[0-9a-f]{24}$\n        chapter_id:\n          type: string\n          pattern: ^ch_[0-9a-f]{24}$\n        steps:\n          type: integer\n          minimum: 0\n          description: How many steps the chapter has now.\n        publish:\n          type: string\n          enum:\n            - draft\n            - ready\n            - other_changes\n          description: \"What publishing the tour would do now. draft: the tour is not published; nothing is public and nothing needs publishing. ready: the tour is published and the only changes not public yet are replaces of this chapter; publish it to put the update live. other_changes: the tour is published and its draft holds more than replaces of this chapter that was never published; publishing would put all of it live.\"\n      additionalProperties: false\n    Manifest:\n      type: object\n      description: \"The tour as the recorder wrote it, at most 262,144 bytes. The server checks every field: unknown fields are dropped, and anything out of range, of the wrong type or over a limit is refused with 400 bad_manifest and the field's path, never cut short. Text is trimmed and may hold no control or format characters. theme, zoom, cover, cta, end and autoplay are read from version 3 only. The full rules are in src/manifest.ts.\"\n      required:\n        - version\n        - generator\n        - title\n        - steps\n      properties:\n        version:\n          type: integer\n          enum:\n            - 1\n            - 2\n            - 3\n          description: Version 1 has steps only; version 2 adds spotlights and notes; version 3 adds cards, the cover, the button, the end card and the tour's look.\n        generator:\n          type: string\n          maxLength: 100\n          description: The program that wrote the manifest.\n        title:\n          type: string\n          minLength: 1\n          maxLength: 200\n          description: The tour's title; for a new chapter, the chapter's.\n        steps:\n          type: array\n          minItems: 1\n          maxItems: 200\n          items:\n            $ref: \"#/components/schemas/ManifestStep\"\n          description: The steps in order. No two may name the same image.\n        spotlight_dim:\n          type:\n            - integer\n            - \"null\"\n          minimum: 10\n          maximum: 90\n          description: \"From version 2: how dark the rest of the picture gets around a spotlight, in percent. Required when a step has a spotlight.\"\n        theme:\n          $ref: \"#/components/schemas/Theme\"\n        zoom:\n          $ref: \"#/components/schemas/Zoom\"\n        cover:\n          oneOf:\n            - $ref: \"#/components/schemas/Cover\"\n            - type: \"null\"\n        cta:\n          oneOf:\n            - $ref: \"#/components/schemas/Link\"\n            - type: \"null\"\n        end:\n          oneOf:\n            - $ref: \"#/components/schemas/EndCard\"\n            - type: \"null\"\n        autoplay:\n          $ref: \"#/components/schemas/Autoplay\"\n    ManifestStep:\n      type: object\n      description: \"One step: a picture, where it was clicked, and what is drawn over it. click is required; null means no click.\"\n      required:\n        - image\n        - width\n        - height\n        - bytes\n        - click\n        - t_ms\n      properties:\n        image:\n          type: string\n          pattern: ^step-[0-9]{3}\\.(png|jpg)$\n          description: The image's name; its ending says whether a PNG or a JPEG will be sent.\n        width:\n          type: integer\n          minimum: 1\n          maximum: 4096\n          description: The image's width in pixels; the image sent must have it.\n        height:\n          type: integer\n          minimum: 1\n          maximum: 4096\n          description: The image's height in pixels; the image sent must have it.\n        bytes:\n          type: integer\n          minimum: 1\n          maximum: 2000000\n          description: The image's length in bytes; the image sent must have it.\n        click:\n          oneOf:\n            - $ref: \"#/components/schemas/Point\"\n            - type: \"null\"\n        t_ms:\n          type: integer\n          minimum: 0\n          description: When the step was recorded, in milliseconds from the start.\n        spotlight:\n          oneOf:\n            - $ref: \"#/components/schemas/Box\"\n            - type: \"null\"\n        notes:\n          type: array\n          maxItems: 20\n          items:\n            $ref: \"#/components/schemas/Note\"\n          description: From version 2.\n        card:\n          oneOf:\n            - $ref: \"#/components/schemas/Card\"\n            - type: \"null\"\n        advance:\n          type: string\n          enum:\n            - hotspot\n            - anywhere\n          description: \"From version 3: whether a click on the hotspot or anywhere moves on. hotspot when absent.\"\n        zoom:\n          type:\n            - boolean\n            - \"null\"\n          description: \"From version 3: this step's own zoom; null follows the tour's.\"\n    Point:\n      type: object\n      required:\n        - x\n        - y\n      properties:\n        x:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the image's width.\n        y:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the image's height.\n    Box:\n      type: object\n      description: A box in percent of the image; it must end inside the image.\n      required:\n        - x\n        - y\n        - w\n        - h\n      properties:\n        x:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the width.\n        y:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the height.\n        w:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Above 0.\n        h:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Above 0.\n    Note:\n      description: A note drawn on the picture.\n      oneOf:\n        - $ref: \"#/components/schemas/TextNote\"\n        - $ref: \"#/components/schemas/BubbleNote\"\n    TextNote:\n      type: object\n      required:\n        - kind\n        - x\n        - y\n        - text\n        - size\n        - color\n      properties:\n        kind:\n          type: string\n          const: text\n        x:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the width.\n        y:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the height.\n        text:\n          type: string\n          minLength: 1\n          maxLength: 500\n          description: May hold line feeds.\n        size:\n          type: number\n          exclusiveMinimum: 0\n          maximum: 100\n          description: The text size, in percent of the image's height.\n        color:\n          type: string\n          pattern: ^#[0-9A-Fa-f]{6}$\n          description: \"The text colour, #rrggbb.\"\n    BubbleNote:\n      type: object\n      required:\n        - kind\n        - x\n        - y\n        - w\n        - h\n        - tail\n        - text\n        - size\n        - color\n        - fill\n      properties:\n        kind:\n          type: string\n          const: bubble\n        x:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the width.\n        y:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Percent of the height.\n        w:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Above 0.\n        h:\n          type: number\n          minimum: 0\n          maximum: 100\n          description: Above 0.\n        tail:\n          $ref: \"#/components/schemas/Point\"\n        text:\n          type: string\n          minLength: 1\n          maxLength: 500\n          description: May hold line feeds.\n        size:\n          type: number\n          exclusiveMinimum: 0\n          maximum: 100\n          description: The text size, in percent of the image's height.\n        color:\n          type: string\n          pattern: ^#[0-9A-Fa-f]{6}$\n          description: \"The text colour, #rrggbb.\"\n        fill:\n          type: string\n          pattern: ^#[0-9A-Fa-f]{6}$\n          description: \"The bubble's colour, #rrggbb.\"\n    Card:\n      type: object\n      description: \"From version 3: the step's card. It needs a title or a body.\"\n      required: []\n      properties:\n        title:\n          type: string\n          maxLength: 80\n          description: Empty when absent.\n        body:\n          type: string\n          maxLength: 300\n          description: May hold line feeds. Empty when absent.\n        next_label:\n          type: string\n          minLength: 1\n          maxLength: 24\n          description: Next when absent.\n        anchor:\n          type: string\n          enum:\n            - hotspot\n            - point\n            - none\n          description: Where the card points. hotspot (the default) needs a step with a click; point needs point.\n        point:\n          oneOf:\n            - $ref: \"#/components/schemas/Point\"\n            - type: \"null\"\n        placement:\n          type: string\n          enum:\n            - auto\n            - top\n            - bottom\n            - left\n            - right\n          description: auto when absent.\n    Link:\n      type: object\n      description: A button with a link.\n      required:\n        - label\n        - url\n      properties:\n        label:\n          type: string\n          minLength: 1\n          maxLength: 24\n          description: The button's text.\n        url:\n          type: string\n          maxLength: 500\n          description: \"An https link with a plain host name: no user name, no IP address, no spaces.\"\n    Theme:\n      type: object\n      description: \"From version 3: the tour's look. Every field has a default.\"\n      required: []\n      properties:\n        card_style:\n          type: string\n          enum:\n            - dark\n            - light\n            - compact\n            - auto\n        accent:\n          type: string\n          pattern: ^#[0-9A-Fa-f]{6}$\n          description: \"#rrggbb.\"\n        hotspot:\n          type: string\n          enum:\n            - pulse\n            - dot\n            - none\n        progress_bar:\n          type: boolean\n        backdrop:\n          type: string\n          pattern: ^(auto|#[0-9A-Fa-f]{6})$\n          description: \"auto, or a colour as #rrggbb.\"\n        spotlight_soft:\n          type: boolean\n    Zoom:\n      type: object\n      description: \"From version 3: whether steps zoom in on the click, and how far.\"\n      required: []\n      properties:\n        enabled:\n          type: boolean\n        percent:\n          type: integer\n          minimum: 105\n          maximum: 140\n    Cover:\n      type: object\n      description: \"From version 3: the page shown before the first step.\"\n      required:\n        - title\n      properties:\n        title:\n          type: string\n          minLength: 1\n          maxLength: 80\n          description: The cover's title.\n        body:\n          type: string\n          maxLength: 200\n          description: May hold line feeds. Empty when absent.\n        button:\n          type: string\n          minLength: 1\n          maxLength: 24\n          description: Start when absent.\n        logo:\n          type:\n            - string\n            - \"null\"\n          enum:\n            - logo.png\n            - logo.jpg\n            - null\n          description: Names the logo this upload will send, by its type; null for none.\n    EndCard:\n      type: object\n      description: \"From version 3: the card shown after the last step.\"\n      required: []\n      properties:\n        text:\n          type: string\n          maxLength: 200\n          description: May hold line feeds. Empty when absent.\n        primary:\n          oneOf:\n            - $ref: \"#/components/schemas/Link\"\n            - type: \"null\"\n        secondary:\n          oneOf:\n            - $ref: \"#/components/schemas/Link\"\n            - type: \"null\"\n        replay:\n          type: boolean\n          description: true when absent.\n    Autoplay:\n      type: object\n      description: \"From version 3: whether the tour moves on by itself, and after how long.\"\n      required: []\n      properties:\n        enabled:\n          type: boolean\n        seconds:\n          type: integer\n          minimum: 2\n          maximum: 20\n  responses:\n    Unauthorized:\n      description: The token or session is missing, malformed, unknown, expired or revoked.\n      content:\n        application/json:\n          schema:\n            $ref: \"#/components/schemas/Unauthorized\"\n";
